        /// <summary>
        /// <para>Specify the behavior of Alt+Tab while the keyboard is grabbed.</para>
        /// </summary>
        /// <remarks>
        /// <para>By default, SDL emulates Alt+Tab functionality while the keyboard is grabbed and your window is full-screen. This prevents the user from getting stuck in your application if you've enabled keyboard grab.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": SDL will not handle Alt+Tab. Your application is responsible for handling Alt+Tab while the keyboard is grabbed.</description></item>
        /// <item><description>"1": SDL will minimize your window when Alt+Tab is pressed (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_ALLOW_ALT_TAB_WHILE_GRABBED">SDL_HINT_ALLOW_ALT_TAB_WHILE_GRABBED</seealso></SDLWiki>
        public static Hint AllowAltTabWhileGrabbed => For(Names.AllowAltTabWhileGrabbed);

        /// <summary>
