        /// </summary>
        /// <remarks>
        /// <para>If set to <c>1</c>, the selected folder will be accessible persistently across app launches. That allows the user to only have to select the directory once, and then the app can access it again in the future without needing to ask the user to select it again.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Persistent folder access is not allowed. (default)</description></item>
        /// <item><description>"1": Persistent folder access is allowed.</description></item>
        /// </list>
        /// <para>This hint should be set before the SDL folder selection dialog is shown, and can be changed between dialog invocations.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.6.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_ANDROID_ALLOW_PERSISTENT_FOLDER_ACCESS">SDL_HINT_ANDROID_ALLOW_PERSISTENT_FOLDER_ACCESS</seealso></SDLWiki>
        public static Hint AndroidAllowPersistentFolderAccess => For(Names.AndroidAllowPersistentFolderAccess);

        /// <summary>
        /// <para>A variable to control whether the SDL activity is allowed to be re-created.</para>
        /// </summary>
        /// <remarks>
        /// <para>If this hint is true, the activity can be recreated on demand by the OS, and Java static data and C++ static data remain with their current values. If this hint is false, then SDL will call exit() when you return from your main function and the application will be terminated and then started fresh each time.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": The application starts fresh at each launch. (default)</description></item>
        /// <item><description>"1": The application activity can be recreated by the OS.</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_ANDROID_ALLOW_RECREATE_ACTIVITY">SDL_HINT_ANDROID_ALLOW_RECREATE_ACTIVITY</seealso></SDLWiki>
        public static Hint AndroidAllowRecreateActivity => For(Names.AndroidAllowRecreateActivity);

        /// <summary>
        /// <para>A variable to control whether the event loop will block itself when the app is paused.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Non blocking.</description></item>
        /// <item><description>"1": Blocking. (default)</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_ANDROID_BLOCK_ON_PAUSE">SDL_HINT_ANDROID_BLOCK_ON_PAUSE</seealso></SDLWiki>
        public static Hint AndroidBlockOnPause => For(Names.AndroidBlockOnPause);

        /// <summary>
        /// <para>A variable to control whether low latency audio should be enabled.</para>
        /// </summary>
        /// <remarks>
        /// <para>Some devices have poor quality output when this is enabled, but this is usually an improvement in audio latency.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Low latency audio is not enabled.</description></item>
        /// <item><description>"1": Low latency audio is enabled. (default)</description></item>
        /// </list>
        /// <para>This hint should be set before SDL audio is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_ANDROID_LOW_LATENCY_AUDIO">SDL_HINT_ANDROID_LOW_LATENCY_AUDIO</seealso></SDLWiki>
        public static Hint AndroidLowLatencyAudio => For(Names.AndroidLowLatencyAudio);

        /// <summary>
        /// <para>A variable to control whether we trap the Android back button to handle it manually.</para>
        /// </summary>
        /// <remarks>
        /// <para>This is necessary for the right mouse button to work on some Android devices, or to be able to trap the back button for use in your code reliably. If this hint is true, the back button will show up as an <see cref="CSDL.EventType.KeyDown">KeyDown</see> / <see cref="CSDL.EventType.KeyUp">KeyUp</see> pair with a keycode of <see cref="CSDL.Input.Scancode.AcBack">AcBack</see>.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Back button will be handled as usual for system. (default)</description></item>
        /// <item><description>"1": Back button will be trapped, allowing you to handle the key press manually. (This will also let right mouse click work on systems where the right mouse button functions as back.)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_ANDROID_TRAP_BACK_BUTTON">SDL_HINT_ANDROID_TRAP_BACK_BUTTON</seealso></SDLWiki>
        public static Hint AndroidTrapBackButton => For(Names.AndroidTrapBackButton);

        /// <summary>
        /// <para>A variable controlling whether controllers used with the Apple TV generate UI events.</para>
        /// </summary>
        /// <remarks>
        /// <para>When UI events are generated by controller input, the app will be backgrounded when the Apple TV remote's menu button is pressed, and when the pause or B buttons on gamepads are pressed.</para>
        /// <para>More information about properly making use of controllers for the Apple TV can be found here: https://developer.apple.com/tvos/human-interface-guidelines/remote-and-controllers/</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Controller input does not generate UI events. (default)</description></item>
        /// <item><description>"1": Controller input generates UI events.</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_APPLE_TV_CONTROLLER_UI_EVENTS">SDL_HINT_APPLE_TV_CONTROLLER_UI_EVENTS</seealso></SDLWiki>
        public static Hint AppleTvControllerUiEvents => For(Names.AppleTvControllerUiEvents);

        /// <summary>
        /// <para>A variable controlling whether the Apple TV remote's joystick axes will automatically match the rotation of the remote.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Remote orientation does not affect joystick axes. (default)</description></item>
        /// <item><description>"1": Joystick axes are based on the orientation of the remote.</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_APPLE_TV_REMOTE_ALLOW_ROTATION">SDL_HINT_APPLE_TV_REMOTE_ALLOW_ROTATION</seealso></SDLWiki>
        public static Hint AppleTvRemoteAllowRotation => For(Names.AppleTvRemoteAllowRotation);

        /// <summary>
        /// <para>A variable setting the app ID string.</para>
        /// </summary>
        /// <remarks>
        /// <para>This string is used by desktop compositors to identify and group windows together, as well as match applications with associated desktop settings and icons.</para>
        /// <para>This will override <see cref="CSDL.Props.AppMetadataIdentifierString">AppMetadataIdentifierString</see>, if set by the application.</para>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_APP_ID">SDL_HINT_APP_ID</seealso></SDLWiki>
        public static Hint AppID => For(Names.AppID);

        /// <summary>
        /// <para>A variable setting the application name.</para>
        /// </summary>
        /// <remarks>
        /// <para>This hint lets you specify the application name sent to the OS when required. For example, this will often appear in volume control applets for audio streams, and in lists of applications which are inhibiting the screensaver. You should use a string that describes your program ("My Game 2: The Revenge")</para>
        /// <para>This will override <see cref="CSDL.Props.AppMetadataNameString">AppMetadataNameString</see>, if set by the application.</para>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_APP_NAME">SDL_HINT_APP_NAME</seealso></SDLWiki>
        public static Hint AppName => For(Names.AppName);

        /// <summary>
        /// <para>A variable controlling response to <c>SDL_assert</c> failures.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following case-sensitive values:</para>
        /// <list type="bullet">
        /// <item><description>"abort": Program terminates immediately.</description></item>
        /// <item><description>"break": Program triggers a debugger breakpoint.</description></item>
        /// <item><description>"retry": Program reruns the <c>SDL_assert</c>'s test again.</description></item>
        /// <item><description>"ignore": Program continues on, ignoring this assertion failure this time.</description></item>
        /// <item><description>"always_ignore": Program continues on, ignoring this assertion failure for the rest of the run.</description></item>
        /// </list>
        /// <para>Note that <see cref="CSDL.Assert.SetHandler">SetHandler</see> offers a programmatic means to deal with assertion failures through a callback, and this hint is largely intended to be used via environment variables by end users and automated tools.</para>
        /// <para>This hint should be set before an assertion failure is triggered and can be changed at any time.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_ASSERT">SDL_HINT_ASSERT</seealso></SDLWiki>
        public static Hint Assert => For(Names.Assert);

        /// <summary>
        /// <para>Specify the default ALSA audio device name.</para>
        /// </summary>
        /// <remarks>
        /// <para>This variable is a specific audio device to open when the "default" audio device is used.</para>
        /// <para>This hint will be ignored when opening the default playback device if <see cref="CSDL.Hints.AudioAlsaDefaultPlaybackDevice">AudioAlsaDefaultPlaybackDevice</see> is set, or when opening the default recording device if <see cref="CSDL.Hints.AudioAlsaDefaultRecordingDevice">AudioAlsaDefaultRecordingDevice</see> is set.</para>
        /// <para>This hint should be set before an audio device is opened.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_ALSA_DEFAULT_DEVICE">SDL_HINT_AUDIO_ALSA_DEFAULT_DEVICE</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Hints.AudioAlsaDefaultPlaybackDevice">AudioAlsaDefaultPlaybackDevice</see></seealso>
        /// <seealso><see cref="CSDL.Hints.AudioAlsaDefaultRecordingDevice">AudioAlsaDefaultRecordingDevice</see></seealso>
        public static Hint AudioAlsaDefaultDevice => For(Names.AudioAlsaDefaultDevice);

        /// <summary>
        /// <para>Specify the default ALSA audio playback device name.</para>
        /// </summary>
        /// <remarks>
        /// <para>This variable is a specific audio device to open for playback, when the "default" audio device is used.</para>
        /// <para>If this hint isn't set, SDL will check <see cref="CSDL.Hints.AudioAlsaDefaultDevice">AudioAlsaDefaultDevice</see> before choosing a reasonable default.</para>
        /// <para>This hint should be set before an audio device is opened.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_ALSA_DEFAULT_PLAYBACK_DEVICE">SDL_HINT_AUDIO_ALSA_DEFAULT_PLAYBACK_DEVICE</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Hints.AudioAlsaDefaultRecordingDevice">AudioAlsaDefaultRecordingDevice</see></seealso>
        /// <seealso><see cref="CSDL.Hints.AudioAlsaDefaultDevice">AudioAlsaDefaultDevice</see></seealso>
        public static Hint AudioAlsaDefaultPlaybackDevice => For(Names.AudioAlsaDefaultPlaybackDevice);

        /// <summary>
        /// <para>Specify the default ALSA audio recording device name.</para>
        /// </summary>
        /// <remarks>
        /// <para>This variable is a specific audio device to open for recording, when the "default" audio device is used.</para>
        /// <para>If this hint isn't set, SDL will check <see cref="CSDL.Hints.AudioAlsaDefaultDevice">AudioAlsaDefaultDevice</see> before choosing a reasonable default.</para>
        /// <para>This hint should be set before an audio device is opened.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_ALSA_DEFAULT_RECORDING_DEVICE">SDL_HINT_AUDIO_ALSA_DEFAULT_RECORDING_DEVICE</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Hints.AudioAlsaDefaultPlaybackDevice">AudioAlsaDefaultPlaybackDevice</see></seealso>
        /// <seealso><see cref="CSDL.Hints.AudioAlsaDefaultDevice">AudioAlsaDefaultDevice</see></seealso>
        public static Hint AudioAlsaDefaultRecordingDevice => For(Names.AudioAlsaDefaultRecordingDevice);

        /// <summary>
        /// <para>A variable controlling the audio category on iOS and macOS.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"playback": Use the AVAudioSessionCategoryPlayback category. (default)</description></item>
        /// <item><description>"ambient": Use the AVAudioSessionCategoryAmbient audio category, will be muted by the phone mute switch.</description></item>
        /// </list>
        /// <para>For more information, see Apple's documentation: https://developer.apple.com/library/content/documentation/Audio/Conceptual/AudioSessionProgrammingGuide/AudioSessionCategoriesandModes/AudioSessionCategoriesandModes.html</para>
        /// <para>This hint should be set before an audio device is opened.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_CATEGORY">SDL_HINT_AUDIO_CATEGORY</seealso></SDLWiki>
        public static Hint AudioCategory => For(Names.AudioCategory);

        /// <summary>
        /// <para>A variable controlling the default audio channel count.</para>
        /// </summary>
        /// <remarks>
        /// <para>If the application doesn't specify the audio channel count when opening the device, this hint can be used to specify a default channel count that will be used. This defaults to "1" for recording and "2" for playback devices.</para>
        /// <para>This hint should be set before an audio device is opened.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_CHANNELS">SDL_HINT_AUDIO_CHANNELS</seealso></SDLWiki>
        public static Hint AudioChannels => For(Names.AudioChannels);

        /// <summary>
        /// <para>Specify an application icon name for an audio device.</para>
        /// </summary>
        /// <remarks>
        /// <para>Some audio backends (such as Pulseaudio and Pipewire) allow you to set an XDG icon name for your application. Among other things, this icon might show up in a system control panel that lets the user adjust the volume on specific audio streams instead of using one giant master volume slider. Note that this is unrelated to the icon used by the windowing system, which may be set with <see cref="CSDL.Video.Window.SetIcon">SetIcon</see> (or via desktop file on Wayland).</para>
        /// <para>Setting this to "" or leaving it unset will have SDL use a reasonable default, "applications-games", which is likely to be installed. See https://specifications.freedesktop.org/icon-theme-spec/icon-theme-spec-latest.html and https://specifications.freedesktop.org/icon-naming-spec/icon-naming-spec-latest.html for the relevant XDG icon specs.</para>
        /// <para>This hint should be set before an audio device is opened.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_DEVICE_APP_ICON_NAME">SDL_HINT_AUDIO_DEVICE_APP_ICON_NAME</seealso></SDLWiki>
        public static Hint AudioDeviceAppIconName => For(Names.AudioDeviceAppIconName);

        /// <summary>
        /// <para>Specify whether this audio device should do audio processing.</para>
        /// </summary>
        /// <remarks>
        /// <para>Some operating systems perform echo cancellation, gain control, and noise reduction as needed. If your application already handles these, you can set this hint to prevent the OS from doing additional audio processing.</para>
        /// <para>This corresponds to the WASAPI audio option <c>AUDCLNT_STREAMOPTIONS_RAW</c>.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": audio processing can be done by the OS. (default)</description></item>
        /// <item><description>"1": audio processing is done by the application.</description></item>
        /// </list>
        /// <para>This hint should be set before an audio device is opened.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.4.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_DEVICE_RAW_STREAM">SDL_HINT_AUDIO_DEVICE_RAW_STREAM</seealso></SDLWiki>
        public static Hint AudioDeviceRawStream => For(Names.AudioDeviceRawStream);

        /// <summary>
        /// <para>A variable controlling device buffer size.</para>
        /// </summary>
        /// <remarks>
        /// <para>This hint is an integer > 0, that represents the size of the device's buffer in sample frames (stereo audio data in 16-bit format is 4 bytes per sample frame, for example).</para>
        /// <para>SDL3 generally decides this value on behalf of the app, but if for some reason the app needs to dictate this (because they want either lower latency or higher throughput AND ARE WILLING TO DEAL WITH what that might require of the app), they can specify it.</para>
        /// <para>SDL will try to accommodate this value, but there is no promise you'll get the buffer size requested. Many platforms won't honor this request at all, or might adjust it.</para>
        /// <para>This hint should be set before an audio device is opened.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_DEVICE_SAMPLE_FRAMES">SDL_HINT_AUDIO_DEVICE_SAMPLE_FRAMES</seealso></SDLWiki>
        public static Hint AudioDeviceSampleFrames => For(Names.AudioDeviceSampleFrames);

        /// <summary>
        /// <para>Specify an audio stream name for an audio device.</para>
        /// </summary>
        /// <remarks>
        /// <para>Some audio backends (such as PulseAudio) allow you to describe your audio stream. Among other things, this description might show up in a system control panel that lets the user adjust the volume on specific audio streams instead of using one giant master volume slider.</para>
        /// <para>This hints lets you transmit that information to the OS. The contents of this hint are used while opening an audio device. You should use a string that describes your what your program is playing ("audio stream" is probably sufficient in many cases, but this could be useful for something like "team chat" if you have a headset playing VoIP audio separately).</para>
        /// <para>Setting this to "" or leaving it unset will have SDL use a reasonable default: "audio stream" or something similar.</para>
        /// <para>Note that while this talks about audio streams, this is an OS-level concept, so it applies to a physical audio device in this case, and not an <see cref="CSDL.Audio.AudioStream">AudioStream</see>, nor an SDL logical audio device.</para>
        /// <para>This hint should be set before an audio device is opened.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_DEVICE_STREAM_NAME">SDL_HINT_AUDIO_DEVICE_STREAM_NAME</seealso></SDLWiki>
        public static Hint AudioDeviceStreamName => For(Names.AudioDeviceStreamName);

        /// <summary>
        /// <para>Specify an application role for an audio device.</para>
        /// </summary>
        /// <remarks>
        /// <para>Some audio backends (such as Pipewire) allow you to describe the role of your audio stream. Among other things, this description might show up in a system control panel or software for displaying and manipulating media playback/recording graphs.</para>
        /// <para>This hints lets you transmit that information to the OS. The contents of this hint are used while opening an audio device. You should use a string that describes your what your program is playing (Game, Music, Movie, etc...).</para>
        /// <para>Setting this to "" or leaving it unset will have SDL use a reasonable default: "Game" or something similar.</para>
        /// <para>Note that while this talks about audio streams, this is an OS-level concept, so it applies to a physical audio device in this case, and not an <see cref="CSDL.Audio.AudioStream">AudioStream</see>, nor an SDL logical audio device.</para>
        /// <para>For Windows WASAPI audio, the following roles are supported, and map to <c>AUDIO_STREAM_CATEGORY</c>:</para>
        /// <list type="bullet">
        /// <item><description>"Other" (default)</description></item>
        /// <item><description>"Communications" - Real-time communications, such as VOIP or chat</description></item>
        /// <item><description>"Game" - Game audio</description></item>
        /// <item><description>"GameChat" - Game chat audio, similar to "Communications" except that this will not attenuate other audio streams</description></item>
        /// <item><description>"Movie" - Music or sound with dialog</description></item>
        /// <item><description>"Media" - Music or sound without dialog</description></item>
        /// </list>
        /// <para>Android's AAudio target supports this hint as of SDL 3.4.4. Android does not support the exact same options as WASAPI, but for portability, will attempt to map these same strings to the <c>aaudio_usage_t</c> constants. For example, "Movie" and "Media" will both map to <c>AAUDIO_USAGE_MEDIA</c>, etc.</para>
        /// <para>If your application applies its own echo cancellation, gain control, and noise reduction it should also set <see cref="CSDL.Hints.AudioDeviceRawStream">AudioDeviceRawStream</see>.</para>
        /// <para>This hint should be set before an audio device is opened.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_DEVICE_STREAM_ROLE">SDL_HINT_AUDIO_DEVICE_STREAM_ROLE</seealso></SDLWiki>
        public static Hint AudioDeviceStreamRole => For(Names.AudioDeviceStreamRole);

        /// <summary>
        /// <para>Specify the input file when recording audio using the disk audio driver.</para>
        /// </summary>
        /// <remarks>
        /// <para>This defaults to "sdlaudio-in.raw"</para>
        /// <para>This hint should be set before an audio device is opened.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_DISK_INPUT_FILE">SDL_HINT_AUDIO_DISK_INPUT_FILE</seealso></SDLWiki>
