        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_DISK_OUTPUT_FILE">SDL_HINT_AUDIO_DISK_OUTPUT_FILE</seealso></SDLWiki>
        public static Hint AudioDiskOutputFile => For(Names.AudioDiskOutputFile);

