        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_DRIVER">SDL_HINT_AUDIO_DRIVER</seealso></SDLWiki>
        public static Hint AudioDriver => For(Names.AudioDriver);

