        public static Hint AudioDuckOthers => For(Names.AudioDuckOthers);

        /// <summary>
        /// <para>A variable controlling the audio rate when using the dummy audio driver.</para>
        /// </summary>
        /// <remarks>
        /// <para>The dummy audio driver normally simulates real-time for the audio rate that was specified, but you can use this variable to adjust this rate higher or lower down to 0. The default value is "1.0".</para>
        /// <para>This hint should be set before an audio device is opened.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_DUMMY_TIMESCALE">SDL_HINT_AUDIO_DUMMY_TIMESCALE</seealso></SDLWiki>
        public static Hint AudioDummyTimescale => For(Names.AudioDummyTimescale);

        /// <summary>
        /// <para>A variable controlling the default audio format.</para>
        /// </summary>
        /// <remarks>
        /// <para>If the application doesn't specify the audio format when opening the device, this hint can be used to specify a default format that will be used.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"U8": Unsigned 8-bit audio</description></item>
        /// <item><description>"S8": Signed 8-bit audio</description></item>
        /// <item><description>"S16LE": Signed 16-bit little-endian audio</description></item>
        /// <item><description>"S16BE": Signed 16-bit big-endian audio</description></item>
        /// <item><description>"S16": Signed 16-bit native-endian audio (default)</description></item>
        /// <item><description>"S32LE": Signed 32-bit little-endian audio</description></item>
        /// <item><description>"S32BE": Signed 32-bit big-endian audio</description></item>
        /// <item><description>"S32": Signed 32-bit native-endian audio</description></item>
        /// <item><description>"F32LE": Floating point little-endian audio</description></item>
        /// <item><description>"F32BE": Floating point big-endian audio</description></item>
        /// <item><description>"F32": Floating point native-endian audio</description></item>
        /// </list>
        /// <para>This hint should be set before an audio device is opened.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_FORMAT">SDL_HINT_AUDIO_FORMAT</seealso></SDLWiki>
        public static Hint AudioFormat => For(Names.AudioFormat);

        /// <summary>
        /// <para>A variable controlling the default audio frequency.</para>
        /// </summary>
        /// <remarks>
        /// <para>If the application doesn't specify the audio frequency when opening the device, this hint can be used to specify a default frequency that will be used. This defaults to "44100".</para>
        /// <para>This hint should be set before an audio device is opened.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_FREQUENCY">SDL_HINT_AUDIO_FREQUENCY</seealso></SDLWiki>
        public static Hint AudioFrequency => For(Names.AudioFrequency);

        /// <summary>
        /// <para>A variable that causes SDL to not ignore audio "monitors".</para>
        /// </summary>
        /// <remarks>
        /// <para>This is currently only used by the PulseAudio driver.</para>
        /// <para>By default, SDL ignores audio devices that aren't associated with physical hardware. Changing this hint to "1" will expose anything SDL sees that appears to be an audio source or sink. This will add "devices" to the list that the user probably doesn't want or need, but it can be useful in scenarios where you want to hook up SDL to some sort of virtual device, etc.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Audio monitor devices will be ignored. (default)</description></item>
        /// <item><description>"1": Audio monitor devices will show up in the device list.</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUDIO_INCLUDE_MONITORS">SDL_HINT_AUDIO_INCLUDE_MONITORS</seealso></SDLWiki>
        public static Hint AudioIncludeMonitors => For(Names.AudioIncludeMonitors);

        /// <summary>
        /// <para>A variable controlling whether SDL updates joystick state when getting input events.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": You'll call <see cref="CSDL.Input.Joysticks.Update">Update</see> manually.</description></item>
        /// <item><description>"1": SDL will automatically call <see cref="CSDL.Input.Joysticks.Update">Update</see>. (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUTO_UPDATE_JOYSTICKS">SDL_HINT_AUTO_UPDATE_JOYSTICKS</seealso></SDLWiki>
        public static Hint AutoUpdateJoysticks => For(Names.AutoUpdateJoysticks);

        /// <summary>
        /// <para>A variable controlling whether SDL updates sensor state when getting input events.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": You'll call <see cref="CSDL.Input.Sensors.Update">Update</see> manually.</description></item>
        /// <item><description>"1": SDL will automatically call <see cref="CSDL.Input.Sensors.Update">Update</see>. (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_AUTO_UPDATE_SENSORS">SDL_HINT_AUTO_UPDATE_SENSORS</seealso></SDLWiki>
        public static Hint AutoUpdateSensors => For(Names.AutoUpdateSensors);

        /// <summary>
        /// <para>Prevent SDL from using version 4 of the bitmap header when saving BMPs.</para>
        /// </summary>
        /// <remarks>
        /// <para>The bitmap header version 4 is required for proper alpha channel support and SDL will use it when required. Should this not be desired, this hint can force the use of the 40 byte header version which is supported everywhere.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Surfaces with a colorkey or an alpha channel are saved to a 32-bit BMP file with an alpha mask. SDL will use the bitmap header version 4 and set the alpha mask accordingly. (default)</description></item>
        /// <item><description>"1": Surfaces with a colorkey or an alpha channel are saved to a 32-bit BMP file without an alpha mask. The alpha channel data will be in the file, but applications are going to ignore it.</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_BMP_SAVE_LEGACY_FORMAT">SDL_HINT_BMP_SAVE_LEGACY_FORMAT</seealso></SDLWiki>
        public static Hint BmpSaveLegacyFormat => For(Names.BmpSaveLegacyFormat);

        /// <summary>
        /// <para>A variable that decides what camera backend to use.</para>
        /// </summary>
        /// <remarks>
        /// <para>By default, SDL will try all available camera backends in a reasonable order until it finds one that can work, but this hint allows the app or user to force a specific target, such as "directshow" if, say, you are on Windows Media Foundations but want to try DirectShow instead.</para>
        /// <para>The default value is unset, in which case SDL will try to figure out the best camera backend on your behalf. This hint needs to be set before <see cref="CSDL.Init.Initialize">Initialize</see> is called to be useful.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_CAMERA_DRIVER">SDL_HINT_CAMERA_DRIVER</seealso></SDLWiki>
        public static Hint CameraDriver => For(Names.CameraDriver);

        /// <summary>
        /// <para>A variable that limits what CPU features are available.</para>
        /// </summary>
        /// <remarks>
        /// <para>By default, SDL marks all features the current CPU supports as available. This hint allows the enabled features to be limited to a subset.</para>
        /// <para>When the hint is unset, or empty, SDL will enable all detected CPU features.</para>
        /// <para>The variable can be set to a comma separated list containing the following items:</para>
        /// <list type="bullet">
        /// <item><description>"all"</description></item>
        /// <item><description>"altivec"</description></item>
        /// <item><description>"sse"</description></item>
        /// <item><description>"sse2"</description></item>
        /// <item><description>"sse3"</description></item>
        /// <item><description>"sse41"</description></item>
        /// <item><description>"sse42"</description></item>
        /// <item><description>"avx"</description></item>
        /// <item><description>"avx2"</description></item>
        /// <item><description>"avx512f"</description></item>
        /// <item><description>"arm-simd"</description></item>
        /// <item><description>"neon"</description></item>
        /// <item><description>"sve2"</description></item>
        /// <item><description>"lsx"</description></item>
        /// <item><description>"lasx"</description></item>
        /// </list>
        /// <para>The items can be prefixed by '+'/'-' to add/remove features.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_CPU_FEATURE_MASK">SDL_HINT_CPU_FEATURE_MASK</seealso></SDLWiki>
        public static Hint CPUFeatureMask => For(Names.CPUFeatureMask);

        /// <summary>
        /// <para>Override for <c>SDL_GetDisplayUsableBounds</c>.</para>
        /// </summary>
        /// <remarks>
        /// <para>If set, this hint will override the expected results for <c>SDL_GetDisplayUsableBounds</c> for display index 0. Generally you don't want to do this, but this allows an embedded system to request that some of the screen be reserved for other uses when paired with a well-behaved application.</para>
        /// <para>The contents of this hint must be 4 comma-separated integers, the first is the bounds x, then y, width and height, in that order.</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_DISPLAY_USABLE_BOUNDS">SDL_HINT_DISPLAY_USABLE_BOUNDS</seealso></SDLWiki>
        public static Hint DisplayUsableBounds => For(Names.DisplayUsableBounds);

        /// <summary>
        /// <para>A variable that enables a fast framebuffer path on DOS.</para>
        /// </summary>
        /// <remarks>
        /// <para>When set to "1", <see cref="CSDL.Video.Window.UpdateWindowSurface">UpdateWindowSurface</see> copies the system-RAM surface directly to VRAM and skips software cursor compositing and vsync.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Use the normal path with cursor compositing and vsync. (default)</description></item>
        /// <item><description>"1": Use the fast direct-to-VRAM path when available.</description></item>
        /// </list>
        /// <para>This hint must be set before the first call to <see cref="CSDL.Video.Window.GetWindowSurface">GetWindowSurface</see>.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.6.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_DOS_ALLOW_DIRECT_FRAMEBUFFER">SDL_HINT_DOS_ALLOW_DIRECT_FRAMEBUFFER</seealso></SDLWiki>
        public static Hint DosAllowDirectFramebuffer => For(Names.DosAllowDirectFramebuffer);

        /// <summary>
        /// <para>Specify the EGL library to load.</para>
        /// </summary>
        /// <remarks>
        /// <para>This hint should be set before creating an OpenGL window or creating an OpenGL context. This hint is only considered if SDL is using EGL to manage OpenGL contexts. If this hint isn't set, SDL will choose a reasonable default.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_EGL_LIBRARY">SDL_HINT_EGL_LIBRARY</seealso></SDLWiki>
        public static Hint EGLLibrary => For(Names.EGLLibrary);

        /// <summary>
        /// <para>Disable giving back control to the browser automatically when running with asyncify.</para>
        /// </summary>
        /// <remarks>
        /// <para>With -s ASYNCIFY, SDL calls emscripten_sleep during operations such as refreshing the screen or polling events.</para>
        /// <para>This hint only applies to the emscripten platform.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Disable emscripten_sleep calls (if you give back browser control manually or use asyncify for other purposes).</description></item>
        /// <item><description>"1": Enable emscripten_sleep calls. (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_EMSCRIPTEN_ASYNCIFY">SDL_HINT_EMSCRIPTEN_ASYNCIFY</seealso></SDLWiki>
        public static Hint EmscriptenAsyncify => For(Names.EmscriptenAsyncify);

        /// <summary>
        /// <para>Specify the CSS selector used for the "default" window/canvas.</para>
        /// </summary>
        /// <remarks>
        /// <para>This hint only applies to the emscripten platform.</para>
        /// <para>This hint should be set before creating a window.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_EMSCRIPTEN_CANVAS_SELECTOR">SDL_HINT_EMSCRIPTEN_CANVAS_SELECTOR</seealso></SDLWiki>
        public static Hint EmscriptenCanvasSelector => For(Names.EmscriptenCanvasSelector);

        /// <summary>
        /// <para>Override the binding element for keyboard inputs for Emscripten builds.</para>
        /// </summary>
        /// <remarks>
        /// <para>This hint only applies to the emscripten platform.</para>
        /// <para>The variable can be one of:</para>
        /// <list type="bullet">
        /// <item><description>"#window": the javascript window object</description></item>
        /// <item><description>"#document": the javascript document object</description></item>
        /// <item><description>"#screen": the javascript window.screen object</description></item>
        /// <item><description>"#canvas": the WebGL canvas element</description></item>
        /// <item><description>"#none": Don't bind anything at all</description></item>
        /// <item><description>any other string without a leading # sign applies to the element on the page with that ID.</description></item>
        /// </list>
        /// <para>This hint should be set before creating a window.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_EMSCRIPTEN_KEYBOARD_ELEMENT">SDL_HINT_EMSCRIPTEN_KEYBOARD_ELEMENT</seealso></SDLWiki>
        public static Hint EmscriptenKeyboardElement => For(Names.EmscriptenKeyboardElement);

        /// <summary>
        /// <para>A variable that controls whether the on-screen keyboard should be shown when text input is active.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"auto": The on-screen keyboard will be shown if there is no physical keyboard attached. (default)</description></item>
        /// <item><description>"0": Do not show the on-screen keyboard.</description></item>
        /// <item><description>"1": Show the on-screen keyboard, if available.</description></item>
        /// </list>
        /// <para>This hint must be set before <see cref="CSDL.Input.Keyboards.StartTextInput">StartTextInput</see> is called</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_ENABLE_SCREEN_KEYBOARD">SDL_HINT_ENABLE_SCREEN_KEYBOARD</seealso></SDLWiki>
        public static Hint EnableScreenKeyboard => For(Names.EnableScreenKeyboard);

        /// <summary>
        /// <para>A variable that controls whether the Steam on-screen keyboard should be shown when text input is active.</para>
        /// </summary>
        /// <remarks>
        /// <para>Steam will set this hint via environment variable for games launched in Big Picture mode. To override this you should call <see cref="CSDL.Hints.Hint.SetWithPriority">SetWithPriority</see> with priority <see cref="CSDL.HintPriority.Override">Override</see>.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Do not show the Steam on-screen keyboard.</description></item>
        /// <item><description>"1": Show the Steam on-screen keyboard.</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.4.12</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_ENABLE_STEAM_SCREEN_KEYBOARD">SDL_HINT_ENABLE_STEAM_SCREEN_KEYBOARD</seealso></SDLWiki>
        public static Hint EnableSteamScreenKeyboard => For(Names.EnableSteamScreenKeyboard);

        /// <summary>
        /// <para>A variable containing a list of evdev devices to use if udev is not available.</para>
        /// </summary>
        /// <remarks>
        /// <para>The list of devices is in the form:</para>
        /// <para>deviceclass:path[,deviceclass:path[,...]]</para>
        /// <para>where device class is an integer representing the <c>SDL_UDEV_deviceclass</c> and path is the full path to the event device.</para>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_EVDEV_DEVICES">SDL_HINT_EVDEV_DEVICES</seealso></SDLWiki>
        public static Hint EvdevDevices => For(Names.EvdevDevices);

        /// <summary>
        /// <para>A variable controlling verbosity of the logging of SDL events pushed onto the internal queue.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values, from least to most verbose:</para>
        /// <list type="bullet">
        /// <item><description>"0": Don't log any events. (default)</description></item>
        /// <item><description>"1": Log most events (other than the really spammy ones).</description></item>
        /// <item><description>"2": Include mouse and finger motion events.</description></item>
        /// </list>
        /// <para>This is generally meant to be used to debug SDL itself, but can be useful for application developers that need better visibility into what is going on in the event queue. Logged events are sent through <c>SDL_Log</c>, which means by default they appear on stdout on most platforms or maybe OutputDebugString() on Windows, and can be funneled by the app with <c>SDL_SetLogOutputFunction</c>, etc.</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_EVENT_LOGGING">SDL_HINT_EVENT_LOGGING</seealso></SDLWiki>
        public static Hint EventLogging => For(Names.EventLogging);

        /// <summary>
        /// <para>A variable that specifies a dialog backend to use.</para>
        /// </summary>
        /// <remarks>
        /// <para>By default, SDL will try all available dialog backends in a reasonable order until it finds one that can work, but this hint allows the app or user to force a specific target.</para>
        /// <para>If the specified target does not exist or is not available, the dialog-related function calls will fail.</para>
        /// <para>This hint currently only applies to platforms using the generic "Unix" dialog implementation, but may be extended to more platforms in the future. Note that some Unix and Unix-like platforms have their own implementation, such as macOS and Haiku.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>NULL: Select automatically (default, all platforms)</description></item>
        /// <item><description>"portal": Use XDG Portals through DBus (Unix only)</description></item>
        /// <item><description>"zenity": Use the Zenity program (Unix only)</description></item>
        /// </list>
        /// <para>More options may be added in the future.</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_FILE_DIALOG_DRIVER">SDL_HINT_FILE_DIALOG_DRIVER</seealso></SDLWiki>
        public static Hint FileDialogDriver => For(Names.FileDialogDriver);

        /// <summary>
        /// <para>A variable controlling whether raising the window should be done more forcefully.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Honor the OS policy for raising windows. (default)</description></item>
        /// <item><description>"1": Force the window to be raised, overriding any OS policy.</description></item>
        /// </list>
        /// <para>At present, this is only an issue under MS Windows, which makes it nearly impossible to programmatically move a window to the foreground, for "security" reasons. See http://stackoverflow.com/a/34414846 for a discussion.</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_FORCE_RAISEWINDOW">SDL_HINT_FORCE_RAISEWINDOW</seealso></SDLWiki>
        public static Hint ForceRaisewindow => For(Names.ForceRaisewindow);

