        /// <remarks>
        /// <para>SDL can try to accelerate the SDL screen surface by using streaming textures with a 3D rendering engine. This variable controls whether and how this is done.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Disable 3D acceleration</description></item>
        /// <item><description>"1": Enable 3D acceleration, using the default renderer. (default)</description></item>
        /// <item><description>"X": Enable 3D acceleration, using X where X is one of the valid rendering drivers. (e.g. "direct3d", "opengl", etc.)</description></item>
        /// </list>
        /// <para>This hint should be set before calling <see cref="CSDL.Video.Window.GetWindowSurface">GetWindowSurface</see></para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_FRAMEBUFFER_ACCELERATION">SDL_HINT_FRAMEBUFFER_ACCELERATION</seealso></SDLWiki>
        public static Hint FramebufferAcceleration => For(Names.FramebufferAcceleration);

