        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_GAMECONTROLLERCONFIG_FILE">SDL_HINT_GAMECONTROLLERCONFIG_FILE</seealso></SDLWiki>
        public static Hint GamecontrollerconfigFile => For(Names.GamecontrollerconfigFile);

