        /// <item><description>"PS4"</description></item>
        /// <item><description>"PS5"</description></item>
        /// <item><description>"SwitchPro"</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_GAMECONTROLLERTYPE">SDL_HINT_GAMECONTROLLERTYPE</seealso></SDLWiki>
