        public static Hint JoystickZeroCenteredDevices => For(Names.JoystickZeroCenteredDevices);

        /// <summary>
        /// <para>A variable that controls keycode representation in keyboard events.</para>
        /// </summary>
        /// <remarks>
        /// <para>This variable is a comma separated set of options for translating keycodes in events:</para>
        /// <list type="bullet">
        /// <item><description>"none": Keycode options are cleared, this overrides other options.</description></item>
        /// <item><description>"hide_numpad": The numpad keysyms will be translated into their non-numpad versions based on the current NumLock state. For example, <c>SDLK_KP_4</c> would become <c>SDLK_4</c> if <c>SDL_KMOD_NUM</c> is set in the event modifiers, and <c>SDLK_LEFT</c> if it is unset.</description></item>
        /// <item><description>"french_numbers": The number row on French keyboards is inverted, so pressing the 1 key would yield the keycode <c>SDLK_1</c>, or '1', instead of <c>SDLK_AMPERSAND</c>, or '&amp;'</description></item>
        /// <item><description>"latin_letters": For keyboards using non-Latin letters, such as Russian or Thai, the letter keys generate keycodes as though it had an English QWERTY layout. e.g. pressing the key associated with <see cref="CSDL.Input.Scancode.A">A</see> on a Russian keyboard would yield 'a' instead of a Cyrillic letter.</description></item>
        /// </list>
        /// <para>The default value for this hint is "french_numbers,latin_letters"</para>
        /// <para>Some platforms like Emscripten only provide modified keycodes and the options are not used.</para>
        /// <para>These options do not affect the return value of <see cref="CSDL.Input.Keyboards.GetKeyFromScancode">GetKeyFromScancode</see> or <see cref="CSDL.Input.Keyboards.GetScancodeFromKey">GetScancodeFromKey</see>, they just apply to the keycode included in key events.</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_KEYCODE_OPTIONS">SDL_HINT_KEYCODE_OPTIONS</seealso></SDLWiki>
        public static Hint KeycodeOptions => For(Names.KeycodeOptions);

        /// <summary>
        /// <para>A variable that controls whether KMSDRM will use "atomic" functionality.</para>
        /// </summary>
        /// <remarks>
        /// <para>The KMSDRM backend can use atomic commits, if both DRM_CLIENT_CAP_ATOMIC and DRM_CLIENT_CAP_UNIVERSAL_PLANES is supported by the system. As of SDL 3.4.0, it will favor this functionality, but in case this doesn't work well on a given system or other surprises, this hint can be used to disable it.</para>
        /// <para>This hint can not enable the functionality if it isn't available.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": SDL will not use the KMSDRM "atomic" functionality.</description></item>
        /// <item><description>"1": SDL will allow usage of the KMSDRM "atomic" functionality. (default)</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.4.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_KMSDRM_ATOMIC">SDL_HINT_KMSDRM_ATOMIC</seealso></SDLWiki>
        public static Hint KMSDRMAtomic => For(Names.KMSDRMAtomic);

        /// <summary>
        /// <para>A variable that controls what KMSDRM device to use.</para>
        /// </summary>
        /// <remarks>
        /// <para>SDL might open something like "/dev/dri/cardNN" to access KMSDRM functionality, where "NN" is a device index number. SDL makes a guess at the best index to use (usually zero), but the app or user can set this hint to a number between 0 and 99 to force selection.</para>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_KMSDRM_DEVICE_INDEX">SDL_HINT_KMSDRM_DEVICE_INDEX</seealso></SDLWiki>
        public static Hint KMSDRMDeviceIndex => For(Names.KMSDRMDeviceIndex);

        /// <summary>
        /// <para>A variable that controls whether SDL requires DRM master access in order to initialize the KMSDRM video backend.</para>
        /// </summary>
        /// <remarks>
        /// <para>The DRM subsystem has a concept of a "DRM master" which is a DRM client that has the ability to set planes, set cursor, etc. When SDL is DRM master, it can draw to the screen using the SDL rendering APIs. Without DRM master, SDL is still able to process input and query attributes of attached displays, but it cannot change display state or draw to the screen directly.</para>
        /// <para>In some cases, it can be useful to have the KMSDRM backend even if it cannot be used for rendering. An app may want to use SDL for input processing while using another rendering API (such as an MMAL overlay on Raspberry Pi) or using its own code to render to DRM overlays that SDL doesn't support.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": SDL will allow usage of the KMSDRM backend without DRM master.</description></item>
        /// <item><description>"1": SDL Will require DRM master to use the KMSDRM backend. (default)</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_KMSDRM_REQUIRE_DRM_MASTER">SDL_HINT_KMSDRM_REQUIRE_DRM_MASTER</seealso></SDLWiki>
        public static Hint KMSDRMRequireDrmMaster => For(Names.KMSDRMRequireDrmMaster);

        /// <summary>
        /// <para>A variable controlling the default SDL log levels.</para>
        /// </summary>
        /// <remarks>
        /// <para>This variable is a comma separated set of category=level tokens that define the default logging levels for SDL applications.</para>
        /// <para>The category can be a numeric category, one of "app", "error", "assert", "system", "audio", "video", "render", "input", "test", or <c>*</c> for any unspecified category.</para>
        /// <para>The level can be a numeric level, one of "verbose", "debug", "info", "warn", "error", "critical", or "quiet" to disable that category.</para>
        /// <para>You can omit the category if you want to set the logging level for all categories.</para>
        /// <para>If this hint isn't set, the default log levels are equivalent to:</para>
        /// <para><c>app=info,assert=warn,test=verbose,*=error</c></para>
        /// <para>If the <c>DEBUG_INVOCATION</c> environment variable is set to "1", the default log levels are equivalent to:</para>
        /// <para><c>assert=warn,test=verbose,*=debug</c></para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_LOGGING">SDL_HINT_LOGGING</seealso></SDLWiki>
        public static Hint Logging => For(Names.Logging);

