        public static Hint MacCtrlClickEmulateRightClick => For(Names.MacCtrlClickEmulateRightClick);

        /// <summary>
        /// <para>A variable controlling whether dispatching OpenGL context updates should block the dispatching thread until the main thread finishes processing on macOS.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Dispatching OpenGL context updates will block the dispatching thread until the main thread finishes processing. (default)</description></item>
        /// <item><description>"1": Dispatching OpenGL context updates will allow the dispatching thread to continue execution.</description></item>
        /// </list>
        /// <para>Generally you want the default, but if you have OpenGL code in a background thread on a Mac, and the main thread hangs because it's waiting for that background thread, but that background thread is also hanging because it's waiting for the main thread to do an update, this might fix your issue.</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MAC_OPENGL_ASYNC_DISPATCH">SDL_HINT_MAC_OPENGL_ASYNC_DISPATCH</seealso></SDLWiki>
        public static Hint MacOpenglAsyncDispatch => For(Names.MacOpenglAsyncDispatch);

        /// <summary>
        /// <para>A variable controlling whether the Option key on macOS should be remapped to act as the Alt key.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"none": The Option key is not remapped to Alt. (default)</description></item>
        /// <item><description>"only_left": Only the left Option key is remapped to Alt.</description></item>
        /// <item><description>"only_right": Only the right Option key is remapped to Alt.</description></item>
        /// <item><description>"both": Both Option keys are remapped to Alt.</description></item>
        /// </list>
        /// <para>This will prevent the triggering of key compositions that rely on the Option key, but will still send the Alt modifier for keyboard events. In the case that both Alt and Option are pressed, the Option key will be ignored. This is particularly useful for applications like terminal emulators and graphical user interfaces (GUIs) that rely on Alt key functionality for shortcuts or navigation. This does not apply to <see cref="CSDL.Input.Keyboards.GetKeyFromScancode">GetKeyFromScancode</see> and only has an effect if IME is enabled.</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MAC_OPTION_AS_ALT">SDL_HINT_MAC_OPTION_AS_ALT</seealso></SDLWiki>
        public static Hint MacOptionAsAlt => For(Names.MacOptionAsAlt);

