        /// <para>A variable controlling whether <see cref="CSDL.EventType.MouseWheel">MouseWheel</see> event values will have momentum on macOS.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": The mouse wheel events will have no momentum. (default)</description></item>
        /// <item><description>"1": The mouse wheel events will have momentum.</description></item>
