        /// <para>This hint needs to be set before <see cref="CSDL.Init.Initialize">Initialize</see>.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MAC_SCROLL_MOMENTUM">SDL_HINT_MAC_SCROLL_MOMENTUM</seealso></SDLWiki>
        public static Hint MacScrollMomentum => For(Names.MacScrollMomentum);

        /// <summary>
        /// <para>Request <c>SDL_AppIterate</c> be called at a specific rate.</para>
        /// </summary>
        /// <remarks>
        /// <para>If this is set to a number, it represents Hz, so "60" means try to iterate 60 times per second. "0" means to iterate as fast as possible. Negative values are illegal, but reserved, in case they are useful in a future revision of SDL.</para>
        /// <para>There are other strings that have special meaning. If set to "waitevent", <c>SDL_AppIterate</c> will not be called until new event(s) have arrived (and been processed by <c>SDL_AppEvent</c>). This can be useful for apps that are completely idle except in response to input. As of SDL 3.6.0, SDL will allow a single call to <c>SDL_AppIterate</c> to proceed without an event immediately after this hint is set to "waitevent", so apps can have a minimum of activity, perhaps to render an initial image to a window before the user has otherwise interacted with the app.</para>
        /// <para>On some platforms, or if you are using <c>SDL_main</c> instead of <c>SDL_AppIterate</c>, this hint is ignored. When the hint can be used, it is allowed to be changed at any time.</para>
        /// <para>This defaults to 0, and specifying NULL for the hint's value will restore the default.</para>
        /// <para>This doesn't have to be an integer value. For example, "59.94" won't be rounded to an integer rate; the digits after the decimal are actually respected.</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MAIN_CALLBACK_RATE">SDL_HINT_MAIN_CALLBACK_RATE</seealso></SDLWiki>
        public static Hint MainCallbackRate => For(Names.MainCallbackRate);

        /// <summary>
        /// <para>A variable controlling whether the mouse is captured while mouse buttons are pressed.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": The mouse is not captured while mouse buttons are pressed.</description></item>
        /// <item><description>"1": The mouse is captured while mouse buttons are pressed.</description></item>
        /// </list>
        /// <para>By default the mouse is captured while mouse buttons are pressed so if the mouse is dragged outside the window, the application continues to receive mouse events until the button is released.</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MOUSE_AUTO_CAPTURE">SDL_HINT_MOUSE_AUTO_CAPTURE</seealso></SDLWiki>
        public static Hint MouseAutoCapture => For(Names.MouseAutoCapture);

        /// <summary>
        /// <para>A variable setting which system cursor to use as the default cursor.</para>
        /// </summary>
        /// <remarks>
        /// <para>This should be an integer corresponding to the <see cref="CSDL.Input.SystemCursor">SystemCursor</see> enum. The default value is zero (<see cref="CSDL.Input.SystemCursor.Default">Default</see>).</para>
        /// <para>This hint needs to be set before <see cref="CSDL.Init.Initialize">Initialize</see>.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MOUSE_DEFAULT_SYSTEM_CURSOR">SDL_HINT_MOUSE_DEFAULT_SYSTEM_CURSOR</seealso></SDLWiki>
        public static Hint MouseDefaultSystemCursor => For(Names.MouseDefaultSystemCursor);

        /// <summary>
        /// <para>A variable setting the double click radius, in pixels.</para>
        /// </summary>
        /// <remarks>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MOUSE_DOUBLE_CLICK_RADIUS">SDL_HINT_MOUSE_DOUBLE_CLICK_RADIUS</seealso></SDLWiki>
        public static Hint MouseDoubleClickRadius => For(Names.MouseDoubleClickRadius);

        /// <summary>
        /// <para>A variable setting the double click time, in milliseconds.</para>
        /// </summary>
        /// <remarks>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MOUSE_DOUBLE_CLICK_TIME">SDL_HINT_MOUSE_DOUBLE_CLICK_TIME</seealso></SDLWiki>
        public static Hint MouseDoubleClickTime => For(Names.MouseDoubleClickTime);

        /// <summary>
        /// <para>A variable setting whether we should scale cursors by the current display scale.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Cursors will not change size based on the display content scale. (default)</description></item>
        /// <item><description>"1": Cursors will automatically match the display content scale (e.g. a 2x sized cursor will be used when the window is on a monitor with 200% scale). This is currently implemented on Windows.</description></item>
        /// </list>
        /// <para>This hint needs to be set before creating cursors.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.4.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MOUSE_DPI_SCALE_CURSORS">SDL_HINT_MOUSE_DPI_SCALE_CURSORS</seealso></SDLWiki>
        public static Hint MouseDpiScaleCursors => For(Names.MouseDpiScaleCursors);

        /// <summary>
        /// <para>A variable controlling whether warping a hidden mouse cursor will activate relative mouse mode.</para>
        /// </summary>
        /// <remarks>
        /// <para>When this hint is set, the mouse cursor is hidden, and multiple warps to the window center occur within a short time period, SDL will emulate mouse warps using relative mouse mode. This can provide smoother and more reliable mouse motion for some older games, which continuously calculate the distance traveled by the mouse pointer and warp it back to the center of the window, rather than using relative mouse motion.</para>
        /// <para>Note that relative mouse mode may have different mouse acceleration behavior than pointer warps.</para>
        /// <para>If your application needs to repeatedly warp the hidden mouse cursor at a high-frequency for other purposes, it should disable this hint.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Attempts to warp the mouse will always be made.</description></item>
        /// <item><description>"1": Some mouse warps will be emulated by forcing relative mouse mode. (default)</description></item>
        /// </list>
        /// <para>If not set, this is automatically enabled unless an application uses relative mouse mode directly.</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MOUSE_EMULATE_WARP_WITH_RELATIVE">SDL_HINT_MOUSE_EMULATE_WARP_WITH_RELATIVE</seealso></SDLWiki>
        public static Hint MouseEmulateWarpWithRelative => For(Names.MouseEmulateWarpWithRelative);

        /// <summary>
        /// <para>Allow mouse click events when clicking to focus an SDL window.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Ignore mouse clicks that activate a window. (default)</description></item>
        /// <item><description>"1": Generate events for mouse clicks that activate a window.</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MOUSE_FOCUS_CLICKTHROUGH">SDL_HINT_MOUSE_FOCUS_CLICKTHROUGH</seealso></SDLWiki>
        public static Hint MouseFocusClickthrough => For(Names.MouseFocusClickthrough);

        /// <summary>
        /// <para>A variable setting the speed scale for mouse motion, in floating point, when the mouse is not in relative mode.</para>
        /// </summary>
        /// <remarks>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MOUSE_NORMAL_SPEED_SCALE">SDL_HINT_MOUSE_NORMAL_SPEED_SCALE</seealso></SDLWiki>
        public static Hint MouseNormalSpeedScale => For(Names.MouseNormalSpeedScale);

        /// <summary>
        /// <para>A variable controlling whether the hardware cursor stays visible when relative mode is active.</para>
        /// </summary>
        /// <remarks>
        /// <para>This variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": The cursor will be hidden while relative mode is active (default)</description></item>
        /// <item><description>"1": The cursor will remain visible while relative mode is active</description></item>
        /// </list>
        /// <para>Note that for systems without raw hardware inputs, relative mode is implemented using warping, so the hardware cursor will visibly warp between frames if this is enabled on those systems.</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MOUSE_RELATIVE_CURSOR_VISIBLE">SDL_HINT_MOUSE_RELATIVE_CURSOR_VISIBLE</seealso></SDLWiki>
        public static Hint MouseRelativeCursorVisible => For(Names.MouseRelativeCursorVisible);

        /// <summary>
        /// <para>A variable controlling whether relative mouse mode constrains the mouse to the center of the window.</para>
        /// </summary>
        /// <remarks>
        /// <para>Constraining to the center of the window works better for FPS games and when the application is running over RDP. Constraining to the whole window works better for 2D games and increases the chance that the mouse will be in the correct position when using high DPI mice.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Relative mouse mode constrains the mouse to the window.</description></item>
        /// <item><description>"1": Relative mouse mode constrains the mouse to the center of the window. (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MOUSE_RELATIVE_MODE_CENTER">SDL_HINT_MOUSE_RELATIVE_MODE_CENTER</seealso></SDLWiki>
        public static Hint MouseRelativeModeCenter => For(Names.MouseRelativeModeCenter);

        /// <summary>
        /// <para>A variable setting the scale for mouse motion, in floating point, when the mouse is in relative mode.</para>
        /// </summary>
        /// <remarks>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MOUSE_RELATIVE_SPEED_SCALE">SDL_HINT_MOUSE_RELATIVE_SPEED_SCALE</seealso></SDLWiki>
        public static Hint MouseRelativeSpeedScale => For(Names.MouseRelativeSpeedScale);

        /// <summary>
        /// <para>A variable controlling whether the system mouse acceleration curve is used for relative mouse motion.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Relative mouse motion will be unscaled. (default)</description></item>
        /// <item><description>"1": Relative mouse motion will be scaled using the system mouse acceleration curve.</description></item>
        /// </list>
        /// <para>If <see cref="CSDL.Hints.MouseRelativeSpeedScale">MouseRelativeSpeedScale</see> is set, that will be applied after system speed scale.</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MOUSE_RELATIVE_SYSTEM_SCALE">SDL_HINT_MOUSE_RELATIVE_SYSTEM_SCALE</seealso></SDLWiki>
        public static Hint MouseRelativeSystemScale => For(Names.MouseRelativeSystemScale);

        /// <summary>
        /// <para>A variable controlling whether a motion event should be generated for mouse warping in relative mode.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Warping the mouse will not generate a motion event in relative mode</description></item>
        /// <item><description>"1": Warping the mouse will generate a motion event in relative mode</description></item>
        /// </list>
        /// <para>By default warping the mouse will not generate motion events in relative mode. This avoids the application having to filter out large relative motion due to warping.</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MOUSE_RELATIVE_WARP_MOTION">SDL_HINT_MOUSE_RELATIVE_WARP_MOTION</seealso></SDLWiki>
        public static Hint MouseRelativeWarpMotion => For(Names.MouseRelativeWarpMotion);

        /// <summary>
        /// <para>A variable controlling whether mouse events should generate synthetic touch events.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Mouse events will not generate touch events. (default for desktop platforms)</description></item>
        /// <item><description>"1": Mouse events will generate touch events. (default for mobile platforms, such as Android and iOS)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MOUSE_TOUCH_EVENTS">SDL_HINT_MOUSE_TOUCH_EVENTS</seealso></SDLWiki>
        public static Hint MouseTouchEvents => For(Names.MouseTouchEvents);

        /// <summary>
        /// <para>A variable controlling whether the keyboard should be muted on the console.</para>
        /// </summary>
        /// <remarks>
        /// <para>Normally the keyboard is muted while SDL applications are running so that keyboard input doesn't show up as key strokes on the console. This hint allows you to turn that off for debugging purposes.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Allow keystrokes to go through to the console.</description></item>
        /// <item><description>"1": Mute keyboard input so it doesn't show up on the console. (default)</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_MUTE_CONSOLE_KEYBOARD">SDL_HINT_MUTE_CONSOLE_KEYBOARD</seealso></SDLWiki>
        public static Hint MuteConsoleKeyboard => For(Names.MuteConsoleKeyboard);

        /// <summary>
        /// <para>Tell SDL not to catch the SIGINT or SIGTERM signals on POSIX platforms.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": SDL will install a SIGINT and SIGTERM handler, and when it catches a signal, convert it into an <see cref="CSDL.EventType.Quit">Quit</see> event. (default)</description></item>
        /// <item><description>"1": SDL will not install a signal handler at all.</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_NO_SIGNAL_HANDLERS">SDL_HINT_NO_SIGNAL_HANDLERS</seealso></SDLWiki>
        public static Hint NoSignalHandlers => For(Names.NoSignalHandlers);

        /// <summary>
        /// <para>A variable controlling what driver to use for OpenGL ES contexts.</para>
        /// </summary>
        /// <remarks>
        /// <para>On some platforms, currently Windows and X11, OpenGL drivers may support creating contexts with an OpenGL ES profile. By default SDL uses these profiles, when available, otherwise it attempts to load an OpenGL ES library, e.g. that provided by the ANGLE project. This variable controls whether SDL follows this default behaviour or will always load an OpenGL ES library.</para>
        /// <para>Circumstances where this is useful include:</para>
        /// <list type="bullet">
        /// <item><description>Testing an app with a particular OpenGL ES implementation, e.g ANGLE, or emulator, e.g. those from ARM, Imagination or Qualcomm.</description></item>
        /// <item><description>Resolving OpenGL ES function addresses at link time by linking with the OpenGL ES library instead of querying them at run time with <see cref="CSDL.Video.GL.GetProcAddress">GetProcAddress</see>.</description></item>
        /// </list>
        /// <para>Caution: for an application to work with the default behaviour across different OpenGL drivers it must query the OpenGL ES function addresses at run time using <see cref="CSDL.Video.GL.GetProcAddress">GetProcAddress</see>.</para>
        /// <para>This variable is ignored on most platforms because OpenGL ES is native or not supported.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Use ES profile of OpenGL, if available. (default)</description></item>
        /// <item><description>"1": Load OpenGL ES library using the default library names.</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_OPENGL_ES_DRIVER">SDL_HINT_OPENGL_ES_DRIVER</seealso></SDLWiki>
        public static Hint OpenglEsDriver => For(Names.OpenglEsDriver);

        /// <summary>
        /// <para>A variable controlling whether to force an sRGB-capable OpenGL context.</para>
        /// </summary>
        /// <remarks>
        /// <para>At OpenGL context creation time, some platforms can request an sRGB-capable context. However, sometimes any form of the request can cause surprising results on some drivers, platforms, and hardware. Usually the surprise is in the form of rendering that is either a little darker or a little brighter than intended.</para>
        /// <para>This hint allows the user to override the app's sRGB requests and either force a specific value, or avoid requesting anything at all, depending on what makes things work correctly for their system.</para>
        /// <para>This is meant as a fail-safe; apps should probably not explicitly set this, and most users should not, either.</para>
        /// <para>Note that some platforms cannot make this request at all, and on all platforms this request can be denied by the operating system.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Force a request for an OpenGL context that is _not_ sRGB-capable.</description></item>
        /// <item><description>"1": Force a request for an OpenGL context that _is_ sRGB-capable.</description></item>
        /// <item><description>"skip": Don't make any request for an sRGB-capable context (don't specify the attribute at all during context creation time).</description></item>
        /// <item><description>any other string is undefined behavior.</description></item>
        /// </list>
        /// <para>If unset, or set to an empty string, SDL will make a request using the value the app specified with the <see cref="CSDL.Video.GLAttr.FramebufferSRGBCapable">FramebufferSRGBCapable</see> attribute.</para>
        /// <para>This hint should be set before an OpenGL context is created.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.4.2</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_OPENGL_FORCE_SRGB_CAPABLE">SDL_HINT_OPENGL_FORCE_SRGB_CAPABLE</seealso></SDLWiki>
        public static Hint OpenglForceSRGBCapable => For(Names.OpenglForceSRGBCapable);

        /// <summary>
        /// <para>A variable controlling whether to force an sRGB-capable OpenGL context.</para>
        /// </summary>
        /// <remarks>
        /// <para>At OpenGL context creation time, some platforms can request an sRGB-capable context. However, sometimes any form of the request can cause surprising results on some drivers, platforms, and hardware. Usually the surprise is in the form of rendering that is either a little darker or a little brighter than intended.</para>
        /// <para>This hint allows the user to override the app's sRGB requests and either force a specific value, or avoid requesting anything at all, depending on what makes things work correctly for their system.</para>
        /// <para>This is meant as a fail-safe; apps should probably not explicitly set this, and most users should not, either.</para>
        /// <para>Note that some platforms cannot make this request at all, and on all platforms this request can be denied by the operating system.</para>
        /// <para>In addition to attempting to obtain the type of sRGB-capable OpenGL context requested by this hint, SDL will try to force the state of GL_FRAMEBUFFER_SRGB on the new context, if appropriate.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Force a request for an OpenGL context that is _not_ sRGB-capable.</description></item>
        /// <item><description>"1": Force a request for an OpenGL context that _is_ sRGB-capable.</description></item>
        /// <item><description>"skip": Don't make any request for an sRGB-capable context (don't specify the attribute at all during context creation time).</description></item>
        /// <item><description>any other string is undefined behavior.</description></item>
        /// </list>
        /// <para>If unset, or set to an empty string, SDL will make a request using the value the app specified with the <see cref="CSDL.Video.GLAttr.FramebufferSRGBCapable">FramebufferSRGBCapable</see> attribute.</para>
        /// <para>This hint should be set before an OpenGL context is created.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.4.2</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_OPENGL_FORCE_SRGB_FRAMEBUFFER">SDL_HINT_OPENGL_FORCE_SRGB_FRAMEBUFFER</seealso></SDLWiki>
        public static Hint OpenglForceSRGBFramebuffer => For(Names.OpenglForceSRGBFramebuffer);

        /// <summary>
        /// <para>Specify the OpenGL library to load.</para>
        /// </summary>
        /// <remarks>
        /// <para>This hint should be set before creating an OpenGL window or creating an OpenGL context. If this hint isn't set, SDL will choose a reasonable default.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_OPENGL_LIBRARY">SDL_HINT_OPENGL_LIBRARY</seealso></SDLWiki>
        public static Hint OpenglLibrary => For(Names.OpenglLibrary);

