        /// <para>This hint should be set before the OpenXR loader is loaded. For example, creating an OpenXR GPU device will load the OpenXR loader.</para>
        /// </remarks>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_OPENXR_LIBRARY">SDL_HINT_OPENXR_LIBRARY</seealso></SDLWiki>
        public static Hint OpenxrLibrary => For(Names.OpenxrLibrary);

