        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_ORIENTATIONS">SDL_HINT_ORIENTATIONS</seealso></SDLWiki>
        public static Hint Orientations => For(Names.Orientations);

        /// <summary>
        /// <para>A variable controlling whether pen events should generate synthetic mouse events.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Pen events will not generate mouse events.</description></item>
        /// <item><description>"1": Pen events will generate mouse events. (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
