        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_PEN_TOUCH_EVENTS">SDL_HINT_PEN_TOUCH_EVENTS</seealso></SDLWiki>
        public static Hint PenTouchEvents => For(Names.PenTouchEvents);

        /// <summary>
        /// <para>A variable controlling the use of a sentinel event when polling the event queue.</para>
        /// </summary>
        /// <remarks>
        /// <para>When polling for events, <see cref="CSDL.Events.Pump">Pump</see> is used to gather new events from devices. If a device keeps producing new events between calls to <see cref="CSDL.Events.Pump">Pump</see>, a poll loop will become stuck until the new events stop. This is most noticeable when moving a high frequency mouse.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Disable poll sentinels.</description></item>
        /// <item><description>"1": Enable poll sentinels. (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_POLL_SENTINEL">SDL_HINT_POLL_SENTINEL</seealso></SDLWiki>
        public static Hint PollSentinel => For(Names.PollSentinel);

