        /// <para>The format of this hint is a comma-separated list of language and locale, combined with an underscore, as is a common format: "en_GB". Locale is optional: "en". So you might have a list like this: "en_GB,jp,es_PT"</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_PREFERRED_LOCALES">SDL_HINT_PREFERRED_LOCALES</seealso></SDLWiki>
        public static Hint PreferredLocales => For(Names.PreferredLocales);

