        /// <remarks>
        /// <para>If the application doesn't pick a specific renderer to use, this variable specifies the name of the preferred renderer. If the preferred renderer can't be initialized, creating a renderer will fail.</para>
        /// <para>This variable is case insensitive and can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"direct3d"</description></item>
        /// <item><description>"direct3d11"</description></item>
        /// <item><description>"direct3d12"</description></item>
        /// <item><description>"opengl"</description></item>
        /// <item><description>"opengles2"</description></item>
        /// <item><description>"opengles"</description></item>
        /// <item><description>"metal"</description></item>
        /// <item><description>"vulkan"</description></item>
        /// <item><description>"gpu"</description></item>
        /// <item><description>"software"</description></item>
        /// </list>
        /// <para>This hint accepts a comma-separated list of driver names, and each will be tried in the order listed when creating a renderer until one succeeds or all of them fail.</para>
        /// <para>The default varies by platform, but it's the first one in the list that is available on the current platform.</para>
        /// <para>This hint should be set before creating a renderer.</para>
        /// </remarks>
