        /// <item><description>"1": Enable debug mode use</description></item>
        /// </list>
        /// <para>This hint should be set before creating a renderer.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_RENDER_GPU_DEBUG">SDL_HINT_RENDER_GPU_DEBUG</seealso></SDLWiki>
        public static Hint RenderGPUDebug => For(Names.RenderGPUDebug);

