        /// <para>A variable controlling whether to prefer a low-power GPU on multi-GPU systems.</para>
        /// </summary>
        /// <remarks>
        /// <para>This variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Prefer high-performance GPU (default)</description></item>
        /// <item><description>"1": Prefer low-power GPU</description></item>
        /// </list>
        /// <para>This hint should be set before creating a renderer.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_RENDER_GPU_LOW_POWER">SDL_HINT_RENDER_GPU_LOW_POWER</seealso></SDLWiki>
        public static Hint RenderGPULowPower => For(Names.RenderGPULowPower);

        /// <summary>
        /// <para>A variable controlling how the 2D render API renders lines.</para>
