        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Use the preferred OS device. (default)</description></item>
        /// <item><description>"1": Select a low power device.</description></item>
        /// </list>
        /// <para>This hint should be set before creating a renderer.</para>
