        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_STORAGE_USER_DRIVER">SDL_HINT_STORAGE_USER_DRIVER</seealso></SDLWiki>
        public static Hint StorageUserDriver => For(Names.StorageUserDriver);

        /// <summary>
        /// <para>Specifies whether <see cref="CSDL.Threads.ThreadPriority.TimeCritical">TimeCritical</see> should be treated as realtime.</para>
        /// </summary>
        /// <remarks>
        /// <para>On some platforms, like Linux, a realtime priority thread may be subject to restrictions that require special handling by the application. This hint exists to let SDL know that the app is prepared to handle said restrictions.</para>
        /// <para>On Linux, SDL will apply the following configuration to any thread that becomes realtime:</para>
        /// <list type="bullet">
        /// <item><description>The SCHED_RESET_ON_FORK bit will be set on the scheduling policy,</description></item>
        /// <item><description>An RLIMIT_RTTIME budget will be configured to the rtkit specified limit.</description></item>
        /// <item><description>Exceeding this limit will result in the kernel sending SIGKILL to the app, refer to the man pages for more information.</description></item>
        /// </list>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": default platform specific behaviour</description></item>
        /// <item><description>"1": Force <see cref="CSDL.Threads.ThreadPriority.TimeCritical">TimeCritical</see> to a realtime scheduling policy</description></item>
        /// </list>
        /// <para>This hint should be set before calling <see cref="CSDL.Threads.Thread.SetCurrentThreadPriority">SetCurrentThreadPriority</see></para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_THREAD_FORCE_REALTIME_TIME_CRITICAL">SDL_HINT_THREAD_FORCE_REALTIME_TIME_CRITICAL</seealso></SDLWiki>
        public static Hint ThreadForceRealtimeTimeCritical => For(Names.ThreadForceRealtimeTimeCritical);

        /// <summary>
        /// <para>A string specifying additional information to use with <see cref="CSDL.Threads.Thread.SetCurrentThreadPriority">SetCurrentThreadPriority</see>.</para>
        /// </summary>
        /// <remarks>
        /// <para>By default <see cref="CSDL.Threads.Thread.SetCurrentThreadPriority">SetCurrentThreadPriority</see> will make appropriate system changes in order to apply a thread priority. For example on systems using pthreads the scheduler policy is changed automatically to a policy that works well with a given priority. Code which has specific requirements can override SDL's default behavior with this hint.</para>
        /// <para>pthread hint values are "current", "other", "fifo" and "rr". Currently no other platform hint values are defined but may be in the future.</para>
        /// <para>On Linux, the kernel may send SIGKILL to realtime tasks which exceed the distro configured execution budget for rtkit. This budget can be queried through RLIMIT_RTTIME after calling <see cref="CSDL.Threads.Thread.SetCurrentThreadPriority">SetCurrentThreadPriority</see>.</para>
        /// <para>This hint should be set before calling <see cref="CSDL.Threads.Thread.SetCurrentThreadPriority">SetCurrentThreadPriority</see></para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_THREAD_PRIORITY_POLICY">SDL_HINT_THREAD_PRIORITY_POLICY</seealso></SDLWiki>
        public static Hint ThreadPriorityPolicy => For(Names.ThreadPriorityPolicy);

        /// <summary>
        /// <para>A variable that controls the timer resolution, in milliseconds.</para>
        /// </summary>
        /// <remarks>
        /// <para>The higher resolution the timer, the more frequently the CPU services timer interrupts, and the more precise delays are, but this takes up power and CPU time. This hint is only used on Windows.</para>
        /// <para>See this blog post for more information: http://randomascii.wordpress.com/2013/07/08/windows-timer-resolution-megawatts-wasted/</para>
        /// <para>The default value is "1".</para>
        /// <para>If this variable is set to "0", the system timer resolution is not set.</para>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_TIMER_RESOLUTION">SDL_HINT_TIMER_RESOLUTION</seealso></SDLWiki>
        public static Hint TimerResolution => For(Names.TimerResolution);

        /// <summary>
        /// <para>A variable controlling whether touch events should generate synthetic mouse events.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Touch events will not generate mouse events.</description></item>
        /// <item><description>"1": Touch events will generate mouse events. (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_TOUCH_MOUSE_EVENTS">SDL_HINT_TOUCH_MOUSE_EVENTS</seealso></SDLWiki>
        public static Hint TouchMouseEvents => For(Names.TouchMouseEvents);

        /// <summary>
        /// <para>A variable controlling whether trackpads should be treated as touch devices.</para>
        /// </summary>
        /// <remarks>
        /// <para>On macOS (and possibly other platforms in the future), SDL will report touches on a trackpad as mouse input, which is generally what users expect from this device; however, these are often actually full multitouch-capable touch devices, so it might be preferable to some apps to treat them as such.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Trackpad will send mouse events. (default)</description></item>
        /// <item><description>"1": Trackpad will send touch events.</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_TRACKPAD_IS_TOUCH_ONLY">SDL_HINT_TRACKPAD_IS_TOUCH_ONLY</seealso></SDLWiki>
        public static Hint TrackpadIsTouchOnly => For(Names.TrackpadIsTouchOnly);

        /// <summary>
        /// <para>A variable controlling whether the Android / tvOS remotes should be listed as joystick devices, instead of sending keyboard events.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Remotes send enter/escape/arrow key events.</description></item>
        /// <item><description>"1": Remotes are available as 2 axis, 2 button joysticks. (default)</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_TV_REMOTE_AS_JOYSTICK">SDL_HINT_TV_REMOTE_AS_JOYSTICK</seealso></SDLWiki>
        public static Hint TvRemoteAsJoystick => For(Names.TvRemoteAsJoystick);

        /// <summary>
        /// <para>A variable controlling whether the screensaver is enabled.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Disable screensaver. (default)</description></item>
        /// <item><description>"1": Enable screensaver.</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_ALLOW_SCREENSAVER">SDL_HINT_VIDEO_ALLOW_SCREENSAVER</seealso></SDLWiki>
        public static Hint VideoAllowScreensaver => For(Names.VideoAllowScreensaver);

        /// <summary>
        /// <para>A comma separated list containing the names of the displays that SDL should sort to the front of the display list.</para>
        /// </summary>
        /// <remarks>
        /// <para>When this hint is set, displays with matching name strings will be prioritized in the list of displays, as exposed by calling <c>SDL_GetDisplays</c>, with the first listed becoming the primary display. The naming convention can vary depending on the environment, but it is usually a connector name (e.g. 'DP-1', 'DP-2', 'HDMI-A-1', etc...).</para>
        /// <para>On Wayland desktops, the connector names associated with displays can be found in the <c>name</c> property of the info output from <c>wayland-info -i wl_output</c>. On X11 desktops, the <c>xrandr</c> utility can be used to retrieve the connector names associated with displays.</para>
        /// <para>This hint is currently supported on the following drivers:</para>
        /// <list type="bullet">
        /// <item><description>KMSDRM (kmsdrm)</description></item>
        /// <item><description>Wayland (wayland)</description></item>
        /// <item><description>X11 (x11)</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_DISPLAY_PRIORITY">SDL_HINT_VIDEO_DISPLAY_PRIORITY</seealso></SDLWiki>
        public static Hint VideoDisplayPriority => For(Names.VideoDisplayPriority);

        /// <summary>
        /// <para>Tell the video driver that we only want a double buffer.</para>
        /// </summary>
        /// <remarks>
        /// <para>By default, most lowlevel 2D APIs will use a triple buffer scheme that wastes no CPU time on waiting for vsync after issuing a flip, but introduces a frame of latency. On the other hand, using a double buffer scheme instead is recommended for cases where low latency is an important factor because we save a whole frame of latency.</para>
        /// <para>We do so by waiting for vsync immediately after issuing a flip, usually just after eglSwapBuffers call in the backend's *_SwapWindow function.</para>
        /// <para>This hint is currently supported on the following drivers:</para>
        /// <list type="bullet">
        /// <item><description>Raspberry Pi (raspberrypi)</description></item>
        /// <item><description>Wayland (wayland)</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_DOUBLE_BUFFER">SDL_HINT_VIDEO_DOUBLE_BUFFER</seealso></SDLWiki>
        public static Hint VideoDoubleBuffer => For(Names.VideoDoubleBuffer);

        /// <summary>
        /// <para>A variable that specifies a video backend to use.</para>
        /// </summary>
        /// <remarks>
        /// <para>By default, SDL will try all available video backends in a reasonable order until it finds one that can work, but this hint allows the app or user to force a specific target, such as "x11" if, say, you are on Wayland but want to try talking to the X server instead.</para>
        /// <para>This hint accepts a comma-separated list of driver names, and each will be tried in the order listed during init, until one succeeds or all of them fail.</para>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_DRIVER">SDL_HINT_VIDEO_DRIVER</seealso></SDLWiki>
        public static Hint VideoDriver => For(Names.VideoDriver);

        /// <summary>
        /// <para>A variable controlling whether the dummy video driver saves output frames.</para>
        /// </summary>
        /// <remarks>
        /// <list type="bullet">
        /// <item><description>"0": Video frames are not saved to disk. (default)</description></item>
        /// <item><description>"1": Video frames are saved to files in the format "<c>SDL_windowX</c>-Y.bmp", where X is the window ID, and Y is the frame number.</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_DUMMY_SAVE_FRAMES">SDL_HINT_VIDEO_DUMMY_SAVE_FRAMES</seealso></SDLWiki>
        public static Hint VideoDummySaveFrames => For(Names.VideoDummySaveFrames);

        /// <summary>
        /// <para>If eglGetPlatformDisplay fails, fall back to calling eglGetDisplay.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to one of the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Do not fall back to eglGetDisplay.</description></item>
        /// <item><description>"1": Fall back to eglGetDisplay if eglGetPlatformDisplay fails. (default)</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_EGL_ALLOW_GETDISPLAY_FALLBACK">SDL_HINT_VIDEO_EGL_ALLOW_GETDISPLAY_FALLBACK</seealso></SDLWiki>
        public static Hint VideoEGLAllowGetdisplayFallback => For(Names.VideoEGLAllowGetdisplayFallback);

        /// <summary>
        /// <para>A variable controlling whether the OpenGL context should be created with EGL.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Use platform-specific GL context creation API (GLX, WGL, CGL, etc). (default)</description></item>
        /// <item><description>"1": Use EGL</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_FORCE_EGL">SDL_HINT_VIDEO_FORCE_EGL</seealso></SDLWiki>
        public static Hint VideoForceEGL => For(Names.VideoForceEGL);

        /// <summary>
        /// <para>A variable that specifies the menu visibility when a window is fullscreen in Spaces on macOS.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": The menu will be hidden when the window is in a fullscreen space, and not accessible by moving the mouse to the top of the screen.</description></item>
        /// <item><description>"1": The menu will be accessible when the window is in a fullscreen space.</description></item>
        /// <item><description>"auto": The menu will be hidden if fullscreen mode was toggled on programmatically via <c>SDL_SetWindowFullscreen()</c>, and accessible if fullscreen was entered via the "fullscreen" button on the window title bar. (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_MAC_FULLSCREEN_MENU_VISIBILITY">SDL_HINT_VIDEO_MAC_FULLSCREEN_MENU_VISIBILITY</seealso></SDLWiki>
        public static Hint VideoMacFullscreenMenuVisibility => For(Names.VideoMacFullscreenMenuVisibility);

        /// <summary>
        /// <para>A variable that specifies the policy for fullscreen Spaces on macOS.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Disable Spaces support (FULLSCREEN_DESKTOP won't use them and <c>SDL_WINDOW_RESIZABLE</c> windows won't offer the "fullscreen" button on their titlebars).</description></item>
        /// <item><description>"1": Enable Spaces support (FULLSCREEN_DESKTOP will use them and <c>SDL_WINDOW_RESIZABLE</c> windows will offer the "fullscreen" button on their titlebars). (default)</description></item>
        /// </list>
        /// <para>This hint should be set before creating a window.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_MAC_FULLSCREEN_SPACES">SDL_HINT_VIDEO_MAC_FULLSCREEN_SPACES</seealso></SDLWiki>
        public static Hint VideoMacFullscreenSpaces => For(Names.VideoMacFullscreenSpaces);

        /// <summary>
        /// <para>A variable controlling whether SDL will attempt to automatically set the destination display to a mode most closely matching that of the previous display if an exclusive fullscreen window is moved onto it.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": SDL will not attempt to automatically set a matching mode on the destination display. If an exclusive fullscreen window is moved to a new display, the window will become fullscreen desktop.</description></item>
        /// <item><description>"1": SDL will attempt to automatically set a mode on the destination display that most closely matches the mode of the display that the exclusive fullscreen window was previously on. (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.4.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_MATCH_EXCLUSIVE_MODE_ON_MOVE">SDL_HINT_VIDEO_MATCH_EXCLUSIVE_MODE_ON_MOVE</seealso></SDLWiki>
        public static Hint VideoMatchExclusiveModeOnMove => For(Names.VideoMatchExclusiveModeOnMove);

        /// <summary>
        /// <para>A variable indicating whether the metal layer drawable size should be updated for the <see cref="CSDL.EventType.WindowPixelSizeChanged">WindowPixelSizeChanged</see> event on macOS.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": the metal layer drawable size will not be updated on the <see cref="CSDL.EventType.WindowPixelSizeChanged">WindowPixelSizeChanged</see> event.</description></item>
        /// <item><description>"1": the metal layer drawable size will be updated on the <see cref="CSDL.EventType.WindowPixelSizeChanged">WindowPixelSizeChanged</see> event. (default)</description></item>
        /// </list>
        /// <para>This hint should be set before <see cref="CSDL.Video.MetalView(Window)">MetalView(Window)</see> called.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.4.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_METAL_AUTO_RESIZE_DRAWABLE">SDL_HINT_VIDEO_METAL_AUTO_RESIZE_DRAWABLE</seealso></SDLWiki>
        public static Hint VideoMetalAutoResizeDrawable => For(Names.VideoMetalAutoResizeDrawable);

        /// <summary>
        /// <para>A variable controlling whether fullscreen windows are minimized when they lose focus.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Fullscreen windows will not be minimized when they lose focus.</description></item>
        /// <item><description>"1": Fullscreen windows are minimized when they lose focus.</description></item>
        /// <item><description>"auto": Fullscreen windows are minimized when they lose focus if they use exclusive fullscreen modes, so the desktop video mode is restored. (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_MINIMIZE_ON_FOCUS_LOSS">SDL_HINT_VIDEO_MINIMIZE_ON_FOCUS_LOSS</seealso></SDLWiki>
        public static Hint VideoMinimizeOnFocusLoss => For(Names.VideoMinimizeOnFocusLoss);

        /// <summary>
        /// <para>A variable controlling whether the offscreen video driver saves output frames.</para>
        /// </summary>
        /// <remarks>
        /// <para>This only saves frames that are generated using software rendering, not accelerated OpenGL rendering.</para>
        /// <list type="bullet">
        /// <item><description>"0": Video frames are not saved to disk. (default)</description></item>
        /// <item><description>"1": Video frames are saved to files in the format "<c>SDL_windowX</c>-Y.bmp", where X is the window ID, and Y is the frame number.</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_OFFSCREEN_SAVE_FRAMES">SDL_HINT_VIDEO_OFFSCREEN_SAVE_FRAMES</seealso></SDLWiki>
        public static Hint VideoOffscreenSaveFrames => For(Names.VideoOffscreenSaveFrames);

        /// <summary>
        /// <para>A variable controlling whether all window operations will block until complete.</para>
        /// </summary>
        /// <remarks>
        /// <para>Window systems that run asynchronously may not have the results of window operations that resize or move the window applied immediately upon the return of the requesting function. Setting this hint will cause such operations to block after every call until the pending operation has completed. Setting this to '1' is the equivalent of calling <see cref="CSDL.Video.Window.SyncWindow">SyncWindow</see> after every function call.</para>
        /// <para>Be aware that amount of time spent blocking while waiting for window operations to complete can be quite lengthy, as animations may have to complete, which can take upwards of multiple seconds in some cases.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Window operations are non-blocking. (default)</description></item>
        /// <item><description>"1": Window operations will block until completed.</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_SYNC_WINDOW_OPERATIONS">SDL_HINT_VIDEO_SYNC_WINDOW_OPERATIONS</seealso></SDLWiki>
        public static Hint VideoSyncWindowOperations => For(Names.VideoSyncWindowOperations);

        /// <summary>
        /// <para>A variable controlling whether the libdecor Wayland backend is allowed to be used.</para>
        /// </summary>
        /// <remarks>
        /// <para>libdecor is used over xdg-shell when xdg-decoration protocol is unavailable.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": libdecor use is disabled.</description></item>
        /// <item><description>"1": libdecor use is enabled. (default)</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_WAYLAND_ALLOW_LIBDECOR">SDL_HINT_VIDEO_WAYLAND_ALLOW_LIBDECOR</seealso></SDLWiki>
        public static Hint VideoWaylandAllowLibdecor => For(Names.VideoWaylandAllowLibdecor);

        /// <summary>
        /// <para>A variable controlling whether video mode emulation is enabled under Wayland.</para>
        /// </summary>
        /// <remarks>
        /// <para>When this hint is set, a standard set of emulated CVT video modes will be exposed for use by the application. If it is disabled, the only modes exposed will be the logical desktop size and, in the case of a scaled desktop, the native display resolution.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Video mode emulation is disabled.</description></item>
        /// <item><description>"1": Video mode emulation is enabled. (default)</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_WAYLAND_MODE_EMULATION">SDL_HINT_VIDEO_WAYLAND_MODE_EMULATION</seealso></SDLWiki>
        public static Hint VideoWaylandModeEmulation => For(Names.VideoWaylandModeEmulation);

        /// <summary>
        /// <para>A variable controlling how modes with a non-native aspect ratio are displayed under Wayland.</para>
        /// </summary>
        /// <remarks>
        /// <para>When this hint is set, the requested scaling will be used when displaying fullscreen video modes that don't match the display's native aspect ratio. This is contingent on compositor viewport support.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"aspect" - Video modes will be displayed scaled, in their proper aspect ratio, with black bars. (default)</description></item>
        /// <item><description>"stretch" - Video modes will be scaled to fill the entire display.</description></item>
        /// <item><description>"none" - Video modes will be displayed as 1:1 with no scaling.</description></item>
        /// </list>
        /// <para>This hint should be set before creating a window.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_WAYLAND_MODE_SCALING">SDL_HINT_VIDEO_WAYLAND_MODE_SCALING</seealso></SDLWiki>
        public static Hint VideoWaylandModeScaling => For(Names.VideoWaylandModeScaling);

        /// <summary>
        /// <para>A variable controlling whether the libdecor Wayland backend is preferred over native decorations.</para>
        /// </summary>
        /// <remarks>
        /// <para>When this hint is set, libdecor will be used to provide window decorations, even if xdg-decoration is available. (Note that, by default, libdecor will use xdg-decoration itself if available).</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": libdecor is enabled only if server-side decorations are unavailable. (default)</description></item>
        /// <item><description>"1": libdecor is always enabled if available.</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_VIDEO_WAYLAND_PREFER_LIBDECOR">SDL_HINT_VIDEO_WAYLAND_PREFER_LIBDECOR</seealso></SDLWiki>
        public static Hint VideoWaylandPreferLibdecor => For(Names.VideoWaylandPreferLibdecor);

        /// <summary>
        /// <para>A variable forcing non-DPI-aware Wayland windows to output at 1:1 scaling.</para>
        /// </summary>
        /// <remarks>
        /// <para>This must be set before initializing the video subsystem.</para>
        /// <para>When this hint is set, Wayland windows that are not flagged as being DPI-aware will be output with scaling designed to force 1:1 pixel mapping.</para>
        /// <para>This is intended to allow legacy applications to be displayed without desktop scaling being applied, and has issues with certain display configurations, as this forces the window to behave in a way that Wayland desktops were not designed to accommodate:</para>
        /// <list type="bullet">
        /// <item><description>Rounding errors can result with odd window sizes and/or desktop scales, which can cause the window contents to appear slightly blurry.</description></item>
        /// <item><description>Positioning the window may be imprecise due to unit conversions and rounding.</description></item>
        /// <item><description>The window may be unusably small on scaled desktops.</description></item>
        /// <item><description>The window may jump in size when moving between displays of different scale factors.</description></item>
        /// <item><description>Displays may appear to overlap when using a multi-monitor setup with scaling enabled.</description></item>
        /// <item><description>Possible loss of cursor precision due to the logical size of the window being reduced.</description></item>
        /// </list>
        /// <para>New applications should be designed with proper DPI awareness handling instead of enabling this.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Windows will be scaled normally.</description></item>
