        /// <summary>
        /// <para>A variable controlling the maximum number of chunks in a WAVE file.</para>
        /// </summary>
        /// <remarks>
        /// <para>This sets an upper bound on the number of chunks in a WAVE file to avoid wasting time on malformed or corrupt WAVE files. This defaults to "10000".</para>
        /// <para>This hint should be set before calling <c>SDL_LoadWAV</c> or <c>SDL_LoadWAV_IO</c></para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WAVE_CHUNK_LIMIT">SDL_HINT_WAVE_CHUNK_LIMIT</seealso></SDLWiki>
        public static Hint WaveChunkLimit => For(Names.WaveChunkLimit);

        /// <summary>
        /// <para>A variable controlling how the fact chunk affects the loading of a WAVE file.</para>
        /// </summary>
        /// <remarks>
        /// <para>The fact chunk stores information about the number of samples of a WAVE file. The Standards Update from Microsoft notes that this value can be used to 'determine the length of the data in seconds'. This is especially useful for compressed formats (for which this is a mandatory chunk) if they produce multiple sample frames per block and truncating the block is not allowed. The fact chunk can exactly specify how many sample frames there should be in this case.</para>
        /// <para>Unfortunately, most application seem to ignore the fact chunk and so SDL ignores it by default as well.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"truncate" - Use the number of samples to truncate the wave data if the fact chunk is present and valid.</description></item>
        /// <item><description>"strict" - Like "truncate", but raise an error if the fact chunk is invalid, not present for non-PCM formats, or if the data chunk doesn't have that many samples.</description></item>
        /// <item><description>"ignorezero" - Like "truncate", but ignore fact chunk if the number of samples is zero.</description></item>
        /// <item><description>"ignore" - Ignore fact chunk entirely. (default)</description></item>
        /// </list>
        /// <para>This hint should be set before calling <c>SDL_LoadWAV</c> or <c>SDL_LoadWAV_IO</c></para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WAVE_FACT_CHUNK">SDL_HINT_WAVE_FACT_CHUNK</seealso></SDLWiki>
        public static Hint WaveFactChunk => For(Names.WaveFactChunk);

        /// <summary>
        /// <para>A variable controlling how the size of the RIFF chunk affects the loading of a WAVE file.</para>
        /// </summary>
        /// <remarks>
        /// <para>The size of the RIFF chunk (which includes all the sub-chunks of the WAVE file) is not always reliable. In case the size is wrong, it's possible to just ignore it and step through the chunks until a fixed limit is reached.</para>
        /// <para>Note that files that have trailing data unrelated to the WAVE file or corrupt files may slow down the loading process without a reliable boundary. By default, SDL stops after 10000 chunks to prevent wasting time. Use <see cref="CSDL.Hints.WaveChunkLimit">WaveChunkLimit</see> to adjust this value.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"force" - Always use the RIFF chunk size as a boundary for the chunk search.</description></item>
        /// <item><description>"ignorezero" - Like "force", but a zero size searches up to 4 GiB. (default)</description></item>
        /// <item><description>"ignore" - Ignore the RIFF chunk size and always search up to 4 GiB.</description></item>
        /// <item><description>"maximum" - Search for chunks until the end of file. (not recommended)</description></item>
        /// </list>
        /// <para>This hint should be set before calling <c>SDL_LoadWAV</c> or <c>SDL_LoadWAV_IO</c></para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WAVE_RIFF_CHUNK_SIZE">SDL_HINT_WAVE_RIFF_CHUNK_SIZE</seealso></SDLWiki>
        public static Hint WaveRiffChunkSize => For(Names.WaveRiffChunkSize);

        /// <summary>
        /// <para>A variable controlling how a truncated WAVE file is handled.</para>
        /// </summary>
        /// <remarks>
        /// <para>A WAVE file is considered truncated if any of the chunks are incomplete or the data chunk size is not a multiple of the block size. By default, SDL decodes until the first incomplete block, as most applications seem to do.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"verystrict" - Raise an error if the file is truncated.</description></item>
        /// <item><description>"strict" - Like "verystrict", but the size of the RIFF chunk is ignored.</description></item>
        /// <item><description>"dropframe" - Decode until the first incomplete sample frame.</description></item>
        /// <item><description>"dropblock" - Decode until the first incomplete block. (default)</description></item>
        /// </list>
        /// <para>This hint should be set before calling <c>SDL_LoadWAV</c> or <c>SDL_LoadWAV_IO</c></para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WAVE_TRUNCATION">SDL_HINT_WAVE_TRUNCATION</seealso></SDLWiki>
        public static Hint WaveTruncation => For(Names.WaveTruncation);

