        /// <summary>
        /// <para>A variable controlling whether menus can be opened with their keyboard shortcut (Alt+mnemonic).</para>
        /// </summary>
        /// <remarks>
        /// <para>If the mnemonics are enabled, then menus can be opened by pressing the Alt key and the corresponding mnemonic (for example, Alt+F opens the File menu). However, in case an invalid mnemonic is pressed, Windows makes an audible beep to convey that nothing happened. This is true even if the window has no menu at all!</para>
        /// <para>Because most SDL applications don't have menus, and some want to use the Alt key for other purposes, SDL disables mnemonics (and the beeping) by default.</para>
        /// <para>Note: This also affects keyboard events: with mnemonics enabled, when a menu is opened from the keyboard, you will not receive a KEYUP event for the mnemonic key, and *might* not receive one for Alt.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Alt+mnemonic does nothing, no beeping. (default)</description></item>
        /// <item><description>"1": Alt+mnemonic opens menus, invalid mnemonics produce a beep.</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOWS_ENABLE_MENU_MNEMONICS">SDL_HINT_WINDOWS_ENABLE_MENU_MNEMONICS</seealso></SDLWiki>
        public static Hint WindowsEnableMenuMnemonics => For(Names.WindowsEnableMenuMnemonics);

        /// <summary>
        /// <para>A variable controlling whether the windows message loop is processed by SDL.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": The window message loop is not run.</description></item>
        /// <item><description>"1": The window message loop is processed in <see cref="CSDL.Events.Pump">Pump</see>. (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOWS_ENABLE_MESSAGELOOP">SDL_HINT_WINDOWS_ENABLE_MESSAGELOOP</seealso></SDLWiki>
        public static Hint WindowsEnableMessageloop => For(Names.WindowsEnableMessageloop);

        /// <summary>
        /// <para>A variable controlling whether SDL will clear the window contents when the WM_ERASEBKGND message is received.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0"/"never": Never clear the window.</description></item>
        /// <item><description>"1"/"initial": Clear the window when the first WM_ERASEBKGND event fires. (default)</description></item>
        /// <item><description>"2"/"always": Clear the window on every WM_ERASEBKGND event.</description></item>
        /// </list>
        /// <para>This hint should be set before creating a window.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOWS_ERASE_BACKGROUND_MODE">SDL_HINT_WINDOWS_ERASE_BACKGROUND_MODE</seealso></SDLWiki>
        public static Hint WindowsEraseBackgroundMode => For(Names.WindowsEraseBackgroundMode);

        /// <summary>
        /// <para>A variable controlling whether SDL uses Kernel Semaphores on Windows.</para>
        /// </summary>
        /// <remarks>
        /// <para>Kernel Semaphores are inter-process and require a context switch on every interaction. On Windows 8 and newer, the WaitOnAddress API is available. Using that and atomics to implement semaphores increases performance. SDL will fall back to Kernel Objects on older OS versions or if forced to by this hint.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Use Atomics and WaitOnAddress API when available, otherwise fall back to Kernel Objects. (default)</description></item>
        /// <item><description>"1": Force the use of Kernel Objects in all cases.</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOWS_FORCE_SEMAPHORE_KERNEL">SDL_HINT_WINDOWS_FORCE_SEMAPHORE_KERNEL</seealso></SDLWiki>
        public static Hint WindowsForceSemaphoreKernel => For(Names.WindowsForceSemaphoreKernel);

        /// <summary>
        /// <para>A variable controlling whether GameInput is used for raw keyboard and mouse on Windows.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": GameInput is not used for raw keyboard and mouse events. (default)</description></item>
        /// <item><description>"1": GameInput is used for raw keyboard and mouse events, if available.</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOWS_GAMEINPUT">SDL_HINT_WINDOWS_GAMEINPUT</seealso></SDLWiki>
        public static Hint WindowsGameinput => For(Names.WindowsGameinput);

        /// <summary>
        /// <para>A variable to specify custom icon resource id from RC file on Windows platform.</para>
        /// </summary>
        /// <remarks>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOWS_INTRESOURCE_ICON">SDL_HINT_WINDOWS_INTRESOURCE_ICON</seealso></SDLWiki>
        public static Hint WindowsIntresourceIcon => For(Names.WindowsIntresourceIcon);

        /// <summary>
        /// <para>A variable to specify custom icon resource id from RC file on Windows platform.</para>
        /// </summary>
        /// <remarks>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOWS_INTRESOURCE_ICON_SMALL">SDL_HINT_WINDOWS_INTRESOURCE_ICON_SMALL</seealso></SDLWiki>
        public static Hint WindowsIntresourceIconSmall => For(Names.WindowsIntresourceIconSmall);

        /// <summary>
        /// <para>A variable controlling whether raw keyboard events are used on Windows.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": The Windows message loop is used for keyboard events. (default)</description></item>
        /// <item><description>"1": Low latency raw keyboard events are used.</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOWS_RAW_KEYBOARD">SDL_HINT_WINDOWS_RAW_KEYBOARD</seealso></SDLWiki>
        public static Hint WindowsRawKeyboard => For(Names.WindowsRawKeyboard);

        /// <summary>
        /// <para>A variable controlling whether or not the RIDEV_NOHOTKEYS flag is set when enabling Windows raw keyboard events.</para>
        /// </summary>
        /// <remarks>
        /// <para>This blocks any hotkeys that have been registered by applications from having any effect beyond generating raw WM_INPUT events.</para>
        /// <para>This flag does not affect system-hotkeys like ALT-TAB or CTRL-ALT-DEL, but does affect the Windows Logo key since it is a userland hotkey registered by explorer.exe.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Hotkeys are not excluded. (default)</description></item>
        /// <item><description>"1": Hotkeys are excluded.</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.4.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOWS_RAW_KEYBOARD_EXCLUDE_HOTKEYS">SDL_HINT_WINDOWS_RAW_KEYBOARD_EXCLUDE_HOTKEYS</seealso></SDLWiki>
        public static Hint WindowsRawKeyboardExcludeHotkeys => For(Names.WindowsRawKeyboardExcludeHotkeys);

        /// <summary>
        /// <para>A variable controlling whether the RIDEV_INPUTSINK flag is set when enabling Windows raw keyboard events.</para>
        /// </summary>
        /// <remarks>
        /// <para>This enables the window to still receive input even if not in foreground.</para>
        /// <para>Focused windows that receive text input will still prevent input events from triggering.</para>
        /// <list type="bullet">
        /// <item><description>"0": Input is not received when not in focus or foreground. (default)</description></item>
        /// <item><description>"1": Input will be received even when not in focus or foreground.</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.4.4</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOWS_RAW_KEYBOARD_INPUTSINK">SDL_HINT_WINDOWS_RAW_KEYBOARD_INPUTSINK</seealso></SDLWiki>
        public static Hint WindowsRawKeyboardInputsink => For(Names.WindowsRawKeyboardInputsink);

        /// <summary>
        /// <para>A variable controlling whether the RIDEV_NOLEGACY flag is set when enabling Windows raw mouse events.</para>
        /// </summary>
        /// <remarks>
        /// <para>If RIDEV_NOLEGACY is set, then Windows mouse events will not be sent for mouse motion while relative mode is enabled. This improves performance when players are using high DPI mice, but should be disabled while showing custom assert dialogs in your application code.</para>
        /// <para>Caution: Windows will not see mouse button releases in relative mode with this active. This means you should not enable relative mode while a mouse button is currently pressed.</para>
        /// <list type="bullet">
        /// <item><description>"0": Windows mouse events will be generated while relative motion is enabled. (default)</description></item>
        /// <item><description>"1": Windows mouse events will not be generated while relative motion is enabled.</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.6.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOWS_RAW_MOUSE_NOLEGACY">SDL_HINT_WINDOWS_RAW_MOUSE_NOLEGACY</seealso></SDLWiki>
        public static Hint WindowsRawMouseNolegacy => For(Names.WindowsRawMouseNolegacy);

        /// <summary>
        /// <para>A variable controlling whether SDL uses the D3D9Ex API introduced in Windows Vista, instead of normal D3D9.</para>
        /// </summary>
        /// <remarks>
        /// <para>Direct3D 9Ex contains changes to state management that can eliminate device loss errors during scenarios like Alt+Tab or UAC prompts. D3D9Ex may require some changes to your application to cope with the new behavior, so this is disabled by default.</para>
        /// <para>For more information on Direct3D 9Ex, see:</para>
        /// <list type="bullet">
        /// <item><description>https://docs.microsoft.com/en-us/windows/win32/direct3darticles/graphics-apis-in-windows-vista#direct3d-9ex</description></item>
        /// <item><description>https://docs.microsoft.com/en-us/windows/win32/direct3darticles/direct3d-9ex-improvements</description></item>
        /// </list>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Use the original Direct3D 9 API. (default)</description></item>
        /// <item><description>"1": Use the Direct3D 9Ex API on Vista and later (and fall back if D3D9Ex is unavailable)</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOWS_USE_D3D9EX">SDL_HINT_WINDOWS_USE_D3D9EX</seealso></SDLWiki>
        public static Hint WindowsUseD3D9EX => For(Names.WindowsUseD3D9EX);

        /// <summary>
        /// <para>A variable controlling whether the window is activated when the <see cref="CSDL.Video.Window.Raise">Raise</see> function is called.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": The window is not activated when the <see cref="CSDL.Video.Window.Raise">Raise</see> function is called.</description></item>
        /// <item><description>"1": The window is activated when the <see cref="CSDL.Video.Window.Raise">Raise</see> function is called. (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOW_ACTIVATE_WHEN_RAISED">SDL_HINT_WINDOW_ACTIVATE_WHEN_RAISED</seealso></SDLWiki>
        public static Hint WindowActivateWhenRaised => For(Names.WindowActivateWhenRaised);

        /// <summary>
        /// <para>A variable controlling whether the window is activated when the <see cref="CSDL.Video.Window.Show">Show</see> function is called.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": The window is not activated when the <see cref="CSDL.Video.Window.Show">Show</see> function is called.</description></item>
        /// <item><description>"1": The window is activated when the <see cref="CSDL.Video.Window.Show">Show</see> function is called. (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOW_ACTIVATE_WHEN_SHOWN">SDL_HINT_WINDOW_ACTIVATE_WHEN_SHOWN</seealso></SDLWiki>
        public static Hint WindowActivateWhenShown => For(Names.WindowActivateWhenShown);

        /// <summary>
        /// <para>If set to "0" then never set the top-most flag on an SDL Window even if the application requests it.</para>
        /// </summary>
        /// <remarks>
        /// <para>This is a debugging aid for developers and not expected to be used by end users.</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": don't allow topmost</description></item>
        /// <item><description>"1": allow topmost (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOW_ALLOW_TOPMOST">SDL_HINT_WINDOW_ALLOW_TOPMOST</seealso></SDLWiki>
        /// <seealso><c>SDL_WINDOW_ALWAYS_ON_TOP</c></seealso>
        public static Hint WindowAllowTopmost => For(Names.WindowAllowTopmost);

        /// <summary>
        /// <para>A variable controlling whether the window frame and title bar are interactive when the cursor is hidden.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": The window frame is not interactive when the cursor is hidden (no move, resize, etc).</description></item>
        /// <item><description>"1": The window frame is interactive when the cursor is hidden. (default)</description></item>
        /// </list>
        /// <para>This hint can be set anytime.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_WINDOW_FRAME_USABLE_WHILE_CURSOR_HIDDEN">SDL_HINT_WINDOW_FRAME_USABLE_WHILE_CURSOR_HIDDEN</seealso></SDLWiki>
        public static Hint WindowFrameUsableWhileCursorHidden => For(Names.WindowFrameUsableWhileCursorHidden);

        /// <summary>
        /// <para>A variable controlling whether X11 windows are marked as override-redirect.</para>
        /// </summary>
        /// <remarks>
        /// <para>If set, this _might_ increase framerate at the expense of the desktop not working as expected. Override-redirect windows aren't noticed by the window manager at all.</para>
        /// <para>You should probably only use this for fullscreen windows, and you probably shouldn't even use it for that. But it's here if you want to try!</para>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": Do not mark the window as override-redirect. (default)</description></item>
        /// <item><description>"1": Mark the window as override-redirect.</description></item>
        /// </list>
        /// <para>This hint should be set before creating a window.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_X11_FORCE_OVERRIDE_REDIRECT">SDL_HINT_X11_FORCE_OVERRIDE_REDIRECT</seealso></SDLWiki>
        public static Hint X11ForceOverrideRedirect => For(Names.X11ForceOverrideRedirect);

        /// <summary>
        /// <para>A variable specifying the type of an X11 window.</para>
        /// </summary>
        /// <remarks>
        /// <para>During <see cref="CSDL.Video.Window(string,int,int,WindowFlags)">Window(string,int,int,WindowFlags)</see>, SDL uses the _NET_WM_WINDOW_TYPE X11 property to report to the window manager the type of window it wants to create. This might be set to various things if <c>SDL_WINDOW_TOOLTIP</c> or <c>SDL_WINDOW_POPUP_MENU</c>, etc, were specified. For "normal" windows that haven't set a specific type, this hint can be used to specify a custom type. For example, a dock window might set this to "_NET_WM_WINDOW_TYPE_DOCK".</para>
        /// <para>This hint should be set before creating a window.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_X11_WINDOW_TYPE">SDL_HINT_X11_WINDOW_TYPE</seealso></SDLWiki>
        public static Hint X11WindowType => For(Names.X11WindowType);

        /// <summary>
        /// <para>Specify the XCB library to load for the X11 driver.</para>
        /// </summary>
        /// <remarks>
        /// <para>The default is platform-specific, often "libX11-xcb.so.1".</para>
        /// <para>This hint should be set before initializing the video subsystem.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_X11_XCB_LIBRARY">SDL_HINT_X11_XCB_LIBRARY</seealso></SDLWiki>
        public static Hint X11XcbLibrary => For(Names.X11XcbLibrary);

        /// <summary>
        /// <para>A variable controlling whether XInput should be used for controller handling.</para>
        /// </summary>
        /// <remarks>
        /// <para>The variable can be set to the following values:</para>
        /// <list type="bullet">
        /// <item><description>"0": XInput is not enabled.</description></item>
        /// <item><description>"1": XInput is enabled. (default)</description></item>
        /// </list>
        /// <para>This hint should be set before SDL is initialized.</para>
        /// </remarks>
        /// <since>This hint is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_HINT_XINPUT_ENABLED">SDL_HINT_XINPUT_ENABLED</seealso></SDLWiki>
        public static Hint XinputEnabled => For(Names.XinputEnabled);

    }
}
